local config = {
  ui_story_5068_50680101_1_dialog_content = "<color=#e8d9bb><size=50>¡¡¡Choque!!!</size></color>",
  ui_story_5068_50680101_2_dialog_content = "(...Por qué...)",
  ui_story_5068_50680101_3_dialog_content = "¡Ay!",
  ui_story_5068_50680101_4_dialog_content = "¿Por qué esta loca muerde a todos los que ve?! ¡Menos mal que reaccioné rápido!",
  ui_story_5068_50680101_5_dialog_content = "¡¿Cómo te atreves a acercarte sigilosamente a nosotros?! ¡No somos un blanco fácil para nadie! ¡Mátalos, ahora!",
  ui_story_5068_50680101_6_dialog_content = "A ver cuál de nosotros termina muerto.",
  ui_story_5068_50680101_7_dialog_content = "(... ¿Cómo terminaron las cosas así?)",
  ui_story_5068_50680101_8_dialog_content = "¡Uh!",
  ui_story_5068_50680101_9_dialog_content = "¡¿Qué demonios?! ¡Esto es una locura! ¡Todos, saquen sus armas! ¡Rápido!!!",
  ui_story_5068_50680101_10_dialog_content = "<color=#e8d9bb>¡Bam! ¡Bam!</color>",
  ui_story_5068_50680101_11_dialog_content = "¡Ahhh!",
  ui_story_5068_50680101_12_dialog_content = "¡No dejes que ninguno de ellos se te escape!!!",
  ui_story_5068_50680101_13_dialog_content = "<color=#e8d9bb><size=45>¡Bam! ¡Bam! ¡Bam!</size></color>",
  ui_story_5068_50680101_14_dialog_content = "¿Qué... Qué está pasando exactamente aquí?!",
  ui_story_5068_50680101_15_dialog_content = "¡Señora Sheol!!!",
  ui_story_5068_50680101_16_dialog_content = "¡Dijiste que este trabajo no era peligroso en absoluto—!!",
  ui_story_5068_50680101_17_dialog_content = "<color=#e8d9bb>Hace un día</color>",
  ui_story_5068_50680101_18_dialog_content = "¡Vaya, este lugar es tan grandioso ahora! Eso es el Gremio de Explorador Nublar para ti, o tal vez esto es todo gracias a ti, señora Sheol?",
  ui_story_5068_50680101_19_dialog_content = "Hace tiempo que no venía aquí, pero este lugar se ha expandido como loco. Casi me pierdo hace un momento.",
  ui_story_5068_50680101_20_dialog_content = "Jeje, ¿es realmente tan impresionante? Estoy seguro de que no es nada comparado con tu magnífico Coloso.",
  ui_story_5068_50680101_21_dialog_content = "Veo que viniste solo hoy... ¿Dónde están las jóvenes que suelen estar a tu lado? No me digas que en realidad se perdieron en el gremio Cloudrover?",
  ui_story_5068_50680101_22_dialog_content = "Bueno, el trabajo fue clasificado como \"muy bajo riesgo\", así que aunque no puedo pelear en absoluto, pensé...",
  ui_story_5068_50680101_23_dialog_content = "A-Ejem! Además, ¡no quiero seguir molestando a mis amigos con cosas así! ¡Ellos también necesitan descansar!",
  ui_story_5068_50680101_24_dialog_content = "Ya veo. Tus palabras no me dejan más opción que reevaluar mi impresión de ti.",
  ui_story_5068_50680101_25_dialog_content = "Hacer cosas por ti mismo no es necesariamente malo, pero nunca olvides que siempre habrá momentos en los que necesitamos depender de los demás.",
  ui_story_5068_50680101_26_dialog_content = "Gracias por la preocupación, pero no te preocupes. Conozco mis propios límites mejor que nadie, por eso siempre tengo cuidado cuando actúo por mi cuenta.",
  ui_story_5068_50680101_27_dialog_content = "No tengo razón para preocuparme si eres tú quien me ayuda. Aun así, debo dejar algo perfectamente claro: tu pago se determinará por la cantidad de cabezas que me traigas.",
  ui_story_5068_50680101_28_dialog_content = "¿¡¿Qué?!?",
  ui_story_5068_50680101_29_dialog_content = "Jejeje, tus reacciones siempre son las más entretenidas. Pero basta de bromas por ahora, pasemos a los asuntos reales.",
  ui_story_5068_50680101_30_dialog_content = "La verdad es que este trabajo no se puede hacer sin ti, por eso no me atrevería a ponerte en peligro.",
  ui_story_5068_50680101_31_dialog_content = "Ven a ver esto.",
  ui_story_5068_50680101_32_dialog_content = "¿Qué es?",
  ui_story_5068_50680101_33_dialog_content = "Tómate tu tiempo y revísalo cuidadosamente.",
  ui_story_5068_50680101_34_dialog_content = "Puedo ver algo vagamente ahí dentro. ¿Es eso... una bola de niebla negra?",
  ui_story_5068_50680101_35_dialog_content = "No... No es una niebla ordinaria. Puedo sentir algo adentro... Una presencia única.",
  ui_story_5068_50680101_36_option_content = "¡Potencia de fuerza!",
  ui_story_5068_50680101_37_dialog_content = "Espera, ¿esto es...?!",
  ui_story_5068_50680101_38_dialog_content = "¡Solía haber Lumina dentro de esta niebla!",
  ui_story_5068_50680101_39_dialog_content = "¿Solía ser?",
  ui_story_5068_50680101_40_dialog_content = "¡Sí! Solía haber Lumina dentro de esta niebla, pero ahora ha desaparecido por completo... Todo excepto por algunos rastros, que solo pude sentir usando mis poderes.",
  ui_story_5068_50680101_41_dialog_content = "... ¿Ves algo más?",
  ui_story_5068_50680101_42_dialog_content = "No.",
  ui_story_5068_50680101_43_dialog_content = "¿Estás seguro? Necesito que estés absolutamente seguro de esto.",
  ui_story_5068_50680101_44_dialog_content = "¿Es por esto que necesitas mi ayuda? ¿Para investigar esta extraña niebla negra?",
  ui_story_5068_50680101_45_dialog_content = "En efecto, pero esto es solo una parte del trabajo. El punto de partida, para ser precisos.",
  ui_story_5068_50680101_46_dialog_content = "Sabía que no sería tan simple.",
  ui_story_5068_50680101_47_dialog_content = "En los últimos días, una enfermedad altamente peligrosa se ha estado propagando por Umbraton... o eso creo.",
  ui_story_5068_50680101_48_dialog_content = "Vaya, creo que nunca te había escuchado sonar tan inseguro.",
  ui_story_5068_50680101_49_dialog_content = "¿En serio? En cualquier caso... \"difundir\" quizás no sea la mejor palabra para describirlo.",
  ui_story_5068_50680101_50_dialog_content = "Esta enfermedad ataca en brotes frecuentes y concentrados, pero no parece seguir ningún patrón. Las áreas afectadas están dispersas al azar por Umbraton, como gotas de lluvia cayendo del cielo. Esto hace que rastrear la enfermedad sea frustrantemente difícil.",
  ui_story_5068_50680101_51_dialog_content = "Entonces, ¿no es contagioso?",
  ui_story_5068_50680101_52_dialog_content = "No puedo estar seguro, pero mis hallazgos iniciales indican que sí. Sin embargo, este no es el aspecto más problemático de la enfermedad.",
  ui_story_5068_50680101_53_dialog_content = "¿Qué sería eso?",
  ui_story_5068_50680101_54_dialog_content = "Los síntomas.",
  ui_story_5068_50680101_55_dialog_content = "¿Qué pasa con ellos?",
  ui_story_5068_50680101_56_dialog_content = "Todos saben que diferentes enfermedades tienen diferentes síntomas. Por ejemplo, una persona con un resfriado mostraría síntomas distintos a alguien con un malestar estomacal.",
  ui_story_5068_50680101_57_dialog_content = "Naturalmente, algunas enfermedades también comparten síntomas similares, como el resfriado común y la neumonía. Sin embargo, este no es el caso con la misteriosa enfermedad de Umbraton.",
  ui_story_5068_50680101_58_dialog_content = "Las personas que han sido afectadas recientemente por esto están mostrando diferentes síntomas...",
  ui_story_5068_50680101_59_dialog_content = "Algunos sienten un dolor insoportable en todo el cuerpo, otros han perdido completamente la voz y algunos se han desplomado de agotamiento debido a una manía incontrolable... Y estos son solo algunos de los muchos síntomas inexplicables que se han reportado recientemente.",
  ui_story_5068_50680101_60_dialog_content = "Entonces, ¿no es posible que estén sufriendo de diferentes enfermedades?",
  ui_story_5068_50680101_61_dialog_content = "No puedo negar esa posibilidad, pero ¿no te parece extraño?",
  ui_story_5068_50680101_62_dialog_content = "Basándonos en nuestros hallazgos anteriores, estas personas no presentaban síntomas antes de enfermarse. Si hubiera sido solo una o dos personas, podríamos llamarlo coincidencia.",
  ui_story_5068_50680101_63_dialog_content = "Pero, ¿qué pasaría si se aplicara a la gran mayoría de los casos? Porque más del noventa por ciento de los pacientes estaban perfectamente sanos un día y al día siguiente estaban gravemente enfermos.",
  ui_story_5068_50680101_64_dialog_content = "¿Podría ser realmente solo una coincidencia?",
  ui_story_5068_50680101_65_dialog_content = "Así que estás diciendo...",
  ui_story_5068_50680101_66_dialog_content = "Esto.",
  ui_story_5068_50680101_67_dialog_content = "Lo siento, Señorita Sheol, pero no entiendo realmente...",
  ui_story_5068_50680101_68_dialog_content = "Esta es la única cosa que todos los pacientes tienen en común.",
  ui_story_5068_50680101_69_dialog_content = "Independientemente de los síntomas o ubicaciones, hay algo que une estos casos aparentemente aislados.",
  ui_story_5068_50680101_70_dialog_content = "¿Quieres decir... esta niebla negra?",
  ui_story_5068_50680101_71_dialog_content = "Exactamente. La mayoría de las personas en cada área infectada informaron haber visto esta niebla negra en algún momento.",
  ui_story_5068_50680101_72_dialog_content = "No hace falta decir que mis subordinados se pusieron en peligro mortal para adquirir este espécimen.",
  ui_story_5068_50680101_73_dialog_content = "¿Peligro mortal?!",
  ui_story_5068_50680101_74_dialog_content = "Ten cuidado... No tengo forma de saber qué pasaría si esta niebla se escapa de su contenedor.",
  ui_story_5068_50680101_75_dialog_content = "Por favor, no omitas detalles importantes como este la próxima vez que pidas ayuda—",
  ui_story_5068_50680101_76_dialog_content = "De todos modos... No esperas que analice la composición de la niebla negra, ¿verdad?",
  ui_story_5068_50680101_77_dialog_content = "Si ese es el caso, lamento decepcionarte, pero mis habilidades psíquicas solo pueden hacer hasta cierto punto.",
  ui_story_5068_50680101_78_dialog_content = "Tengan la seguridad de que analizar la niebla negra no es la razón por la que los he llamado aquí hoy.",
  ui_story_5068_50680101_79_dialog_content = "Simplemente necesito tu ayuda para localizar el origen de la niebla.",
  ui_story_5068_50680101_80_dialog_content = "¿Sospechas... que alguien <color=#FFB400>a propósito</color> liberó la niebla negra en Umbraton?",
  ui_story_5068_50680101_81_dialog_content = "Todavía no puedo decirlo con certeza, y es precisamente por eso que necesito tu ayuda.",
  ui_story_5068_50680101_82_dialog_content = "Este trabajo no me parece muy seguro...",
  ui_story_5068_50680101_83_dialog_content = "Solo necesito que me informes sobre cualquier hallazgo sospechoso. No es necesario profundizar demasiado en las cosas, mucho menos interactuar con los demás.",
  ui_story_5068_50680101_84_dialog_content = "La legendaria Caelestite no debería tener problemas con algo tan simple.",
  ui_story_5068_50680101_85_dialog_content = "Si ese es el caso, debería poder evitar la mayoría de situaciones peligrosas usando mis poderes. Pero aún así...",
  ui_story_5068_50680101_86_dialog_content = "Estoy bien preparado para compensarte generosamente por tus problemas. Si el trabajo lleva más tiempo del esperado, también te pagaré en consecuencia.",
  ui_story_5068_50680101_87_dialog_content = "Ah, eso no es lo que quiero decir... Solo hay una cosa que aún no entiendo.",
  ui_story_5068_50680101_88_dialog_content = "La niebla negra no parece estar afectando al Gremio de Explorador Nublar de manera notable, entonces, ¿por qué te esfuerzas tanto en investigarla?",
  ui_story_5068_50680101_89_dialog_content = "O tal vez, sin que yo lo sepa, ¿de repente te has vuelto apasionado por la caridad?",
  ui_story_5068_50680101_90_dialog_content = "... ¿De verdad así es como me ves? Todavía tienes un largo camino por recorrer, joven.",
  ui_story_5068_50680101_91_dialog_content = "Hacer negocios es más que solo comprar o vender. No es que sea caritativo; simplemente estoy pagando los costos necesarios para garantizar la continuidad del negocio.",
  ui_story_5068_50680101_92_dialog_content = "Entonces eso es...",
  ui_story_5068_50680101_93_dialog_content = "Bien, eso cubre todo. El resto depende de ti ahora, PlayerName.",
  ui_story_5068_50680101_94_dialog_content = "<color=#e8d9bb>Después de que te vayas...</color>",
  ui_story_5068_50680101_95_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_5068_50680101_96_dialog_content = "Soy yo.",
  ui_story_5068_50680101_97_dialog_content = "¡Señora Sheol! ¡Estaré allí enseguida!",
  ui_story_5068_50680101_98_dialog_content = "Está bien...",
  ui_story_5068_50680201_1_dialog_content = "Terminé en un lugar tan sombrío persiguiendo esa niebla negra... Me pregunto si este lugar está bajo la jurisdicción de Umbraton. Realmente espero que sí.",
  ui_story_5068_50680201_2_dialog_content = "<color=#e8d9bb>Uf... uf...</color>",
  ui_story_5068_50680201_3_dialog_content = "Vaya, acabo de sentir un escalofrío en la columna. ¿Alguien realmente vive en estas casas? Se siente como si algo fuera a saltar de repente hacia mí...",
  ui_story_5068_50680201_4_option_content = "Debería simplemente volver.",
  ui_story_5068_50680201_5_dialog_content = "No, no, ya he llegado hasta aquí. Debería...",
  ui_story_5068_50680201_6_option_content = "¡Debería seguir!",
  ui_story_5068_50680201_7_dialog_content = "Solo tengo que encontrar de dónde vino la niebla negra e informarlo a Lady Sheol. No tengo que preocuparme por lo que suceda después de eso.",
  ui_story_5068_50680201_8_dialog_content = "Además, ¡no puedo simplemente rendirme a mitad de camino! ¡Tengo que endurecerme!",
  ui_story_5068_50680201_9_option_content = "¡Potencia de fuerza!",
  ui_story_5068_50680201_10_dialog_content = "Hmm... Parece que me estoy acercando al origen de la niebla negra.",
  ui_story_5068_50680201_11_dialog_content = "Realmente no esperaba que las cosas fueran tan fluidas. Supongo que Lady Sheol no mentía acerca del nivel de peligro del trabajo después de todo.",
  ui_story_5068_50680201_12_dialog_content = "¡Ayuda! ¿Hay alguien ahí? ¡Ayuda!",
  ui_story_5068_50680201_13_dialog_content = "¿Eh? ¿Estoy escuchando cosas o alguien acaba de pedir ayuda?",
  ui_story_5068_50680201_14_dialog_content = "¡Tú, tú, tú! ¡Mantente alejado! ¡Ayuda! ¡Alguien, AYUDA—!",
  ui_story_5068_50680201_15_dialog_content = "Rugido-!",
  ui_story_5068_50680201_16_dialog_content = "¡Ahhhh—!",
  ui_story_5068_50680201_17_dialog_content = "¡Oh, no! No hay tiempo—",
  ui_story_5068_50680201_18_dialog_content = "¡Fuera de mi camino!!!",
  ui_story_5068_50680201_19_dialog_content = "¿Ah?",
  ui_story_5068_50680201_20_dialog_content = "¡¿Cómo lograron los Eclipsites llegar a este lugar?!",
  ui_story_5068_50680202_1_dialog_content = "(¡Increíble! ¡Ella eliminó a todos los Eclipsites antes de que tuviera tiempo de reaccionar!)",
  ui_story_5068_50680202_2_dialog_content = "No debería haber más Eclipsites, al menos por ahora. ¿Estás bien?",
  ui_story_5068_50680202_3_dialog_content = "... Estoy bien, no te preocupes. Fue por poco. Gracias por salvarme, <color=#FFB400>Señorita Asistente</color>.",
  ui_story_5068_50680202_4_dialog_content = "No hay problema. No puedo creer que los Eclipsites lograron colarse aquí, aunque todavía sea parte de Umbraton. ¡Habla de mala suerte!",
  ui_story_5068_50680202_5_dialog_content = "¿Cómo terminaste encontrándote con ellos?",
  ui_story_5068_50680202_6_dialog_content = "N-No estoy muy seguro. Acababa de terminar el trabajo y, de camino a casa, la niebla apareció de repente, todo se volvió completamente oscuro y luego...",
  ui_story_5068_50680202_7_dialog_content = "(... \"¿Niebla\"? \"¿Todo se volvió completamente negro\"? ¿Podría ser lo que creo que es?!)",
  ui_story_5068_50680202_8_dialog_content = "Entonces, de repente me sentí enfermo y pensé en ir al <color=#FFB400>doctor</color> para que me revisara, pero...",
  ui_story_5068_50680202_9_dialog_content = "Pero luego te encontraste con esas cosas... Hoy realmente no es tu día, ¿verdad?",
  ui_story_5068_50680202_10_dialog_content = "Así es como es. Gente como nosotros no tiene otra opción más que vivir en estos barrios marginales remotos.",
  ui_story_5068_50680202_11_dialog_content = "Cuando algo sale mal aquí... a nadie le importa en absoluto. Si no tuviera la suerte de contar con tu ayuda, probablemente habría...",
  ui_story_5068_50680202_12_dialog_content = "¡Oye, oye, deja de llorar! Estás bien, ¿no? Yo también salí sin un rasguño, ¡así que todo está bien!",
  ui_story_5068_50680202_13_dialog_content = "¿Aún puedes pararte?",
  ui_story_5068_50680202_14_dialog_content = "¿Eh? Parece que mis piernas me están fallando...",
  ui_story_5068_50680202_15_dialog_content = "Suspiro...",
  ui_story_5068_50680202_16_dialog_content = "Lo siento, soy realmente inútil. No es gran cosa, pero yo...",
  ui_story_5068_50680202_17_dialog_content = "No, eso no es lo que quise decir. Todos se asustan cuando ven a los Eclipsites, así que no seas tan duro contigo mismo.",
  ui_story_5068_50680202_18_dialog_content = "Es solo que... el <color=#FFB400>doctor</color> va a tener un paciente más hoy.",
  ui_story_5068_50680202_19_dialog_content = "Aquí, dame tu mano y te ayudaré a levantarte.",
  ui_story_5068_50680202_20_dialog_content = "Gracias, señorita asistente. Realmente lo siento; me salvaste, pero te he causado tantos problemas... En realidad, ya podría estar solo ahora...",
  ui_story_5068_50680202_21_dialog_content = "¿Qué, crees que puedes salir de aquí por tu cuenta? ¡Vamos, no me hagas reír!",
  ui_story_5068_50680202_22_dialog_content = "¿Qué pasaría si aparecen más Eclipsites? ¿Qué harías entonces?",
  ui_story_5068_50680202_23_dialog_content = "Además, acabo de terminar de hacer unos recados para el médico y estaba de camino de regreso a la clínica. Si tienes suficiente energía para hablar un montón de tonterías, entonces levántate y ven conmigo.",
  ui_story_5068_50680202_24_dialog_content = "Gracias...",
  ui_story_5068_50680202_25_dialog_content = "... Guárdalo para cuando el médico te trate, ¡ahora muévete!",
  ui_story_5068_50680202_26_dialog_content = "Espera... No estoy viendo cosas, ¿verdad? Esa señora...",
  ui_story_5068_50680202_27_dialog_content = "¡Su cuerpo parece estar cubierto de algo que se asemeja a la niebla negra!",
  ui_story_5068_50680202_28_dialog_content = "Esto es malo, ¡necesito alcanzarlos!",
  ui_story_5068_50680301_1_dialog_content = "Lo sabía. ¡La presencia de la niebla negra es extremadamente intensa aquí!",
  ui_story_5068_50680301_2_dialog_content = "Esta casa no resalta en ningún aspecto, lo que la convierte en un escondite perfecto... Realmente no puedo creer que haya terminado mi trabajo tan fácilmente.",
  ui_story_5068_50680301_3_dialog_content = "Ahora solo tengo que informar a la Señora Sheol y—",
  ui_story_5068_50680301_4_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5068_50680301_5_dialog_content = "...",
  ui_story_5068_50680301_6_dialog_content = "...",
  ui_story_5068_50680301_7_dialog_content = "Uh... H-Hola?",
  ui_story_5068_50680301_8_dialog_content = "¿Quién eres? ¿Y por qué estás rondando por aquí?",
  ui_story_5068_50680301_9_dialog_content = "Ah, yo...",
  ui_story_5068_50680301_10_dialog_content = "Es porque... Mi estómago... Me duele...",
  ui_story_5068_50680301_11_dialog_content = "Escuché que esto era una clínica...",
  ui_story_5068_50680301_12_dialog_content = "...",
  ui_story_5068_50680301_13_dialog_content = "Mi estómago... Realmente duele...",
  ui_story_5068_50680301_14_dialog_content = "...",
  ui_story_5068_50680301_15_dialog_content = "(Esa mirada fría... Es como si estuviera mirando directamente a mi alma. No me digas... ¿¡Ya ha visto a través de mí?!)",
  ui_story_5068_50680301_16_dialog_content = "... Ah... Bueno... Parece que estoy en el lugar equivocado... ¿P-Podrías indicarme dónde está la clínica?",
  ui_story_5068_50680301_17_dialog_content = "Yo-yo puedo ir a buscarlo por mi cuenta...",
  ui_story_5068_50680301_18_dialog_content = "Perdón por molestar...",
  ui_story_5068_50680301_19_dialog_content = "¡Espera!",
  ui_story_5068_50680301_20_dialog_content = "(¡Oh no, me descubrieron! ¡Será mejor que huya!)",
  ui_story_5068_50680301_21_dialog_content = "¡¿No me escuchaste?! ¡Dije espera!",
  ui_story_5068_50680301_22_dialog_content = "¿Eh? ¿Va a atacarme ella?!",
  ui_story_5068_50680302_1_dialog_content = "Gruñido—",
  ui_story_5068_50680302_2_dialog_content = "Uf... ¿Así que había un Eclipsite detrás de mí todo el tiempo? Estaba bien al principio, pero su ataque de hace un momento fue lo suficientemente aterrador como para hacerme sentir enfermo...",
  ui_story_5068_50680302_3_dialog_content = "\"¿Bien\"? Pensé que dijiste que te dolía el estómago.",
  ui_story_5068_50680302_4_dialog_content = "—!!!",
  ui_story_5068_50680302_5_dialog_content = "Ahora que lo mencionas, está empezando a doler de nuevo... El Eclipsite debe haberme asustado tanto que olvidé el dolor.",
  ui_story_5068_50680302_6_dialog_content = "Urgh... Mi estómago... Me está matando...",
  ui_story_5068_50680302_7_dialog_content = "Qué tipo raro... Venga, supongo.",
  ui_story_5068_50680302_8_dialog_content = "Estás en el lugar correcto. Esta es la clínica.",
  ui_story_5068_50680302_9_dialog_content = "... Ya deberías estar bien. Ve a casa y descansa mucho, y no te esfuerces demasiado en el trabajo durante los próximos dos días.",
  ui_story_5068_50680302_10_dialog_content = "Gracias, <color=#FFB400>Doctor</color>. Me siento mucho mejor ahora. Pero...",
  ui_story_5068_50680302_11_dialog_content = "¿Qué pasa? ¿Todavía te sientes enfermo?",
  ui_story_5068_50680302_12_dialog_content = "No, no, no. Tus habilidades médicas son excepcionales y ahora me siento bien. Es solo que... la factura médica...",
  ui_story_5068_50680302_13_dialog_content = "No te preocupes si no puedes cubrir mi tarifa ahora mismo. Simplemente apúntalo en tu cuenta y págame más tarde como de costumbre.",
  ui_story_5068_50680302_14_dialog_content = "Todos se conocen por aquí, así que solo regresa cuando tengas el dinero.",
  ui_story_5068_50680302_15_dialog_content = "¡Muchas gracias! ¡Realmente lo aprecio! Siempre estoy endeudado y es realmente vergonzoso...",
  ui_story_5068_50680302_16_dialog_content = "No te estreses tanto por eso. Nunca es buena idea dejar un problema médico sin tratar, así que ven a verme cuando lo necesites, ¿de acuerdo?",
  ui_story_5068_50680302_17_dialog_content = "¡Sí! Oh... Parece que hay un nuevo paciente. No tomaré más de su tiempo, Doctor.",
  ui_story_5068_50680302_18_dialog_content = "(¿La fuente de la niebla negra es... el doctor?)",
  ui_story_5068_50680302_19_dialog_content = "(Se siente muy similar, pero... algo también se siente muy diferente. ¿Qué podría ser?)",
  ui_story_5068_50680302_20_dialog_content = "Hola, ¿cuál parece ser el problema?",
  ui_story_5068_50680302_21_dialog_content = "(Si realmente es ella... ¿qué podría estar buscando?)",
  ui_story_5068_50680302_22_dialog_content = "(¿Lo está haciendo a propósito? ¿Podría estar enfermando a la gente para tener más pacientes?)",
  ui_story_5068_50680302_23_dialog_content = "(No, eso no puede ser. Acabo de ver cómo condonaba las facturas médicas de esa chica por ahora, y parece que no es la primera vez tampoco.)",
  ui_story_5068_50680302_24_dialog_content = "El médico te hizo una pregunta, ¡así que deja de mirarla de esa manera! Te advierto que si pones tus ojos en algo que no debes, ni siquiera ella podrá arreglar lo que les pase a tus ojos.",
  ui_story_5068_50680302_25_dialog_content = "Ya basta, estás asustando a nuestro paciente. Ahora bien... ¿Qué es lo que le pasa exactamente?",
  ui_story_5068_50680302_26_dialog_content = "Se quejaba de que le dolía el estómago antes...",
  ui_story_5068_50680302_27_dialog_content = "Sí... Es cierto, es mi estómago.",
  ui_story_5068_50680302_28_dialog_content = "Eso me recuerda, ¿quién te habló de la clínica en primer lugar?",
  ui_story_5068_50680302_29_dialog_content = "Ah... S-Solo un amable desconocido. Vio cuánto dolor tenía, así que me habló de una clínica cercana y cómo encontrarla.",
  ui_story_5068_50680302_30_dialog_content = "—!",
  ui_story_5068_50680302_31_dialog_content = "...",
  ui_story_5068_50680302_32_dialog_content = "(Uh, ¿qué está pasando? ¿Dije algo que no debería haber dicho...?)",
  ui_story_5068_50680302_33_dialog_content = "Uhhhhh... Ugh, ¡ahhhh!",
  ui_story_5068_50680302_34_dialog_content = "¡Duele! ¡AHHH! ¡Me está matando!",
  ui_story_5068_50680302_35_dialog_content = "Este es-",
  ui_story_5068_50680302_36_dialog_content = "Hace un momento estaba recuperándose, ¿cómo puede ser esto? Si no lo trato de inmediato...",
  ui_story_5068_50680302_37_dialog_content = "Me siento realmente enfermo... Doctor, ¿voy a morir? Por favor, no quiero morir...",
  ui_story_5068_50680302_38_dialog_content = "Aaaaaahhh!!!",
  ui_story_5068_50680302_39_dialog_content = "¡Deja de pensar en cosas así! Te atenderé de inmediato, así que no tengas miedo. Todo va a estar bien...",
  ui_story_5068_50680302_40_dialog_content = "(eso es—)",
  ui_story_5068_50680302_41_dialog_content = "¿Ah?",
  ui_story_5068_50680302_42_dialog_content = "Las cosas te entran por un oído y te salen por el otro, ¿verdad? ¿No te dije que mantuvieras tus ojos para ti mismo?!",
  ui_story_5068_50680302_43_dialog_content = "¡Lo siento! ¡No quise mirar!",
  ui_story_5068_50680302_44_dialog_content = "(... Si no me equivoco, esta doctora está usando Lumina para curar a sus pacientes. La niebla solo sale mientras los trata.)",
  ui_story_5068_50680302_45_dialog_content = "(Pero es diferente de lo que Lady Sheol me dio. Su niebla está llena de Lumina, mientras que la muestra de Lady Sheol no tiene nada en absoluto.)",
  ui_story_5068_50680302_46_dialog_content = "(¿Significa esto que estaba equivocado? No, ¡todavía es demasiado pronto para afirmarlo! Tal vez la Lumina solo está presente durante su tratamiento y luego se agota una vez que termina. Después de eso...)",
  ui_story_5068_50680302_47_dialog_content = "(Sin Lumina restante, se convierte en esa dañina niebla negra. Es posible que la doctora no sepa cómo manejarla, así que la desecha en secreto.)",
  ui_story_5068_50680302_48_dialog_content = "(Pero estas son solo mis propias suposiciones; si son correctas o no, es algo que Lady Sheol debe averiguar. Podría ser que esté completamente equivocado en todo esto.)",
  ui_story_5068_50680302_49_dialog_content = "Estás bien ahora. Intenta descansar un poco y estarás curado cuando despiertes.",
  ui_story_5068_50680302_50_dialog_content = "Emm...",
  ui_story_5068_50680302_51_dialog_content = "¡Uf!",
  ui_story_5068_50680302_52_dialog_content = "(Ella se ve aliviada al ver a su paciente en condición estable. No creo que lo esté fingiendo tampoco.)",
  ui_story_5068_50680302_53_dialog_content = "Ya has tratado a demasiados pacientes hoy, Doctor. Descansa por ahora y yo me \"encargaré\" de este último paciente.",
  ui_story_5068_50680302_54_dialog_content = "Está bien, puedo cuidar de él. Pero... probablemente tengas razón sobre tener demasiados pacientes. Ya no aceptaremos nuevos pacientes hoy, así que por favor cierra la puerta.",
  ui_story_5068_50680302_55_dialog_content = "Seguro.",
  ui_story_5068_50680302_56_dialog_content = "(?!)",
  ui_story_5068_50680302_57_dialog_content = "Mi asistente me dice que estás sufriendo de dolor de estómago, ¿es cierto?",
  ui_story_5068_50680302_58_dialog_content = "¿Es una enfermedad crónica?",
  ui_story_5068_50680302_59_dialog_content = "Bueno...",
  ui_story_5068_50680302_60_dialog_content = "¿O tal vez comiste algo que no estaba muy limpio?",
  ui_story_5068_50680302_61_dialog_content = "Em...",
  ui_story_5068_50680302_62_dialog_content = "Mmm... Parece que no estás dispuesto a decírmelo, pero no te preocupes...",
  ui_story_5068_50680302_63_dialog_content = "Tengo muchos medicamentos muy efectivos para combatir el dolor de estómago, sin importar la causa.",
  ui_story_5068_50680302_64_dialog_content = "¿Ves?",
  ui_story_5068_50680302_65_dialog_content = "Con solo una inyección, ninguna cantidad de dolor te molestará nunca más. Ni siquiera recordarás el dolor que sentías antes.",
  ui_story_5068_50680302_66_dialog_content = "¡Esp. un segundo!",
  ui_story_5068_50680302_67_dialog_content = "¡... De repente me siento mucho mejor!",
  ui_story_5068_50680302_68_dialog_content = "...",
  ui_story_5068_50680302_69_dialog_content = "¡S-Perdón por molestarte, Doctor! Definitivamente volveré a verte si mi dolor regresa!",
  ui_story_5068_50680302_70_dialog_content = "Adiós—",
  ui_story_5068_50680302_71_dialog_content = "Ahora, ¿quién dijo que podías irte?",
  ui_story_5068_50680302_72_dialog_content = "(Parece que escapar ya no es una opción...)",
  ui_story_5068_50680302_73_dialog_content = "Tú... no viniste aquí buscando tratamiento, ¿verdad?",
  ui_story_5068_50680401_1_dialog_content = "Tú... no viniste aquí buscando tratamiento, ¿verdad?",
  ui_story_5068_50680401_2_dialog_content = "¡Lo hice, lo juro! Es solo que de repente me siento mucho mejor ahora.",
  ui_story_5068_50680401_3_dialog_content = "Es una locura, ¿verdad? Tal vez... Tal vez fue solo algo pasajero?",
  ui_story_5068_50680401_4_dialog_content = "¿Nos tomas por idiotas o qué? ¡Deja de actuar ya!",
  ui_story_5068_50680401_5_dialog_content = "Eres de los que tienen que aprender las cosas de la manera difícil, ¿verdad? No me importa enseñarte una lección, pero te advierto...",
  ui_story_5068_50680401_6_dialog_content = "Esto podría <color=#FFB400>realmente</color> doler!",
  ui_story_5068_50680401_7_dialog_content = "¡¿Q-Qué me vas a hacer?!",
  ui_story_5068_50680401_8_dialog_content = "Muy bien... Eso es suficiente, ustedes dos.",
  ui_story_5068_50680401_9_dialog_content = "No pareces tener malas intenciones, considerando que no has intentado atacarnos después de todo este tiempo... ¿Tengo razón?",
  ui_story_5068_50680401_10_dialog_content = "... ¡Así es!",
  ui_story_5068_50680401_11_dialog_content = "Otra vez esto no, Doctor.",
  ui_story_5068_50680401_12_dialog_content = "Eres una persona de corazón tan tierno. No creo que sea algo malo, o si no, no lo diría... De todos modos, si sigues confiando en los demás tan fácilmente, tarde o temprano—",
  ui_story_5068_50680401_13_dialog_content = "Sé que te preocupas por mí, pero sé lo que estoy haciendo. Confía en mí.",
  ui_story_5068_50680401_14_dialog_content = "Además, este lugar nos pertenece. Mientras estés a mi lado, no tengo nada de qué preocuparme.",
  ui_story_5068_50680401_15_dialog_content = "...",
  ui_story_5068_50680401_16_dialog_content = "Ahora bien, ¿podrías decirnos por qué estabas fingiendo estar enfermo?",
  ui_story_5068_50680401_17_dialog_content = "Pero mi estómago realmente me dolió justo ahora...",
  ui_story_5068_50680401_18_dialog_content = "¡Ugh, ya déjalo! Descubriste tu propia tapadera hace mucho tiempo, ¿o aún no te has dado cuenta?!",
  ui_story_5068_50680401_19_dialog_content = "¿Realmente es tan mala mi actuación...?",
  ui_story_5068_50680401_20_dialog_content = "No tomó mucho para que lo admitieras... Debes ser una persona bastante honesta.",
  ui_story_5068_50680401_21_dialog_content = "Si tu actuación fuera mejor, tendríamos muchas más sospechas de ti. Para ser honesto, la parte más reveladora de tu actuación fue una sola declaración.",
  ui_story_5068_50680401_22_dialog_content = "Ah... S-Solo un amable desconocido. Vio cuánto dolor tenía, así que me habló de una clínica cercana y cómo encontrarla.",
  ui_story_5068_50680401_23_dialog_content = "Mi clínica no es muy grande y está bastante bien escondida. Además, tenemos una regla muy especial aquí:",
  ui_story_5068_50680401_24_dialog_content = "Cualquier persona que visite la clínica debe ser presentada personalmente por alguien que conozcamos.",
  ui_story_5068_50680401_25_dialog_content = "Todos mis pacientes saben que no acepto pacientes con antecedentes desconocidos, lo que significa que nunca me recomendarían a alguien desconocido para ellos.",
  ui_story_5068_50680401_26_dialog_content = "En cuanto dijiste eso, ambos supimos que nos estabas mintiendo.",
  ui_story_5068_50680401_27_dialog_content = "Entiendo...",
  ui_story_5068_50680401_28_dialog_content = "Mi asistente y yo debemos mantener un perfil bajo por razones que no podemos revelar.",
  ui_story_5068_50680401_29_dialog_content = "Ya te he dicho mucho más de lo necesario... Entonces, ¿te importaría decirnos por qué estás aquí?",
  ui_story_5068_50680401_30_dialog_content = "La verdad es... me asignaron investigar una extraña enfermedad que se ha propagado en Umbraton últimamente. Y mi investigación me trajo a este lugar.",
  ui_story_5068_50680401_31_dialog_content = "Al principio pensé que tenía una pista importante, pero al final creo que me equivoqué de persona...",
  ui_story_5068_50680401_32_dialog_content = "...",
  ui_story_5068_50680401_33_dialog_content = "...",
  ui_story_5068_50680401_34_dialog_content = "¡¿Sigues inventando historias, eh?!",
  ui_story_5068_50680401_35_dialog_content = "¡N-No, lo juro que es la verdad!",
  ui_story_5068_50680401_36_dialog_content = "No hay necesidad de seguir perdiendo el tiempo con este tipo, Doctor. Además, él ya vio su método de tratamiento hace un momento.",
  ui_story_5068_50680401_37_dialog_content = "¿Es... es eso así? En ese caso, lo único que puedo decir es que lo siento.",
  ui_story_5068_50680401_38_dialog_content = "(¡Oh no, parece que estoy en verdaderos problemas ahora...! ¿¡Qué van a hacer conmigo?!)",
  ui_story_5068_50680401_39_option_content = "¡Potencia de fuerza!",
  ui_story_5068_50680401_40_dialog_content = "(Lo siento mucho, pero para mantener a <color=#FFB400>Eleanor</color> y a mí mismo a salvo, no tengo otra opción más que hacer esto.)",
  ui_story_5068_50680401_41_dialog_content = "(Debes haber asumido este trabajo hace poco, ¿verdad? Si es así, esta inyección te hará olvidar todo lo que sucedió en el último mes...)",
  ui_story_5068_50680401_42_dialog_content = "(Una vez que estés dormido, haré que Eleanor te lleve a un lugar seguro. No deberías haber entrado en esta clínica.)",
  ui_story_5068_50680401_43_dialog_content = "(<color=#FFB400>Rebecca</color> sigue siendo una persona demasiado amable.)",
  ui_story_5068_50680401_44_dialog_content = "(Sabía que este tipo no era bueno desde el momento en que entró y comenzó a decir tonterías. Si dependiera de mí, lo habría echado con el resto de la basura sin pensarlo dos veces.)",
  ui_story_5068_50680401_45_dialog_content = "(Esta Rebecca dama parece que no quiere lastimarme, y su asistente realmente la escucha.)",
  ui_story_5068_50680401_46_dialog_content = "(Si nunca me hubiera entrometido en sus asuntos, probablemente ella no tendría que hacerme esto. Pero tal vez... tal vez aún tengo una oportunidad de ganarme su confianza.)",
  ui_story_5068_50680401_47_dialog_content = "(¡Solo tengo una oportunidad para esto!)",
  ui_story_5068_50680401_48_dialog_content = "¡Espera! ¿Has estado tratando a muchos pacientes con síntomas misteriosos últimamente?",
  ui_story_5068_50680401_49_dialog_content = "¡Deja de intentar ganar tiempo!",
  ui_story_5068_50680401_50_dialog_content = "... Está bien, déjalo hablar.",
  ui_story_5068_50680401_51_dialog_content = "Eh, bueno, no sé por qué ustedes dos están siendo tan secretos, pero puedo ver que realmente tienen en cuenta los intereses de sus pacientes, Doctor.",
  ui_story_5068_50680401_52_dialog_content = "Tal vez podamos trabajar juntos para encontrar la raíz de estas extrañas enfermedades.",
  ui_story_5068_50680401_53_dialog_content = "Mmm... Mencionaste que tu trabajo implica investigar una enfermedad extraña, ¿verdad? ¿Has hecho algún otro progreso?",
  ui_story_5068_50680401_54_dialog_content = "Solo esto.",
  ui_story_5068_50680401_X54_dialog_content = "¿Habías visto algo así antes, Dr. Rebecca? Como médico, deberías saber mucho más sobre esto que yo.",
  ui_story_5068_50680401_55_dialog_content = "—!!!",
  ui_story_5068_50680401_56_dialog_content = "¡¿Q-Qué haces con esto?! ¿Dónde lo encontraste?!",
  ui_story_5068_50680401_57_dialog_content = "¡Espera! ¿Cómo sabes el nombre de Rebecca?!",
  ui_story_5068_50680401_58_dialog_content = "(¡Ah! ¡Se me escapó!)",
  ui_story_5068_50680401_59_dialog_content = "¡Escúpelo antes de que te lo haga escupir a la fuerza!",
  ui_story_5068_50680401_60_dialog_content = "Espera, a menos que... estés con los <color=#FFB400>Lobos Negros</color>, ¿verdad?!",
  ui_story_5068_50680401_61_dialog_content = "¿Los Lobos Negros? ¿Quiénes son?",
  ui_story_5068_50680401_62_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5068_50680401_63_dialog_content = "¿Alguien dijo que esto era una clínica? ¿Un basurero como este?",
  ui_story_5068_50680401_64_dialog_content = "Está un poco deteriorado, pero mira las cosas adentro; ¡esto es realmente una clínica!",
  ui_story_5068_50680401_65_dialog_content = "Esas máscaras... ¿Realmente los Lobos Negros están detrás de todo esto?",
  ui_story_5068_50680401_66_dialog_content = "¡No intentes nada gracioso! ¡Tus amigos aquí ya nos contaron todo!",
  ui_story_5068_50680401_67_dialog_content = "¡Espera, detente! ¡No conozco a estas personas en absoluto! ¡No estamos trabajando juntos, lo juro!",
  ui_story_5068_50680401_68_dialog_content = "Tsk. ¡Doctor! Doctor, salga rápido. ¿Quién es el médico aquí?",
  ui_story_5068_50680401_69_dialog_content = "Escuché que el médico de aquí puede tratar enfermedades causadas por la niebla negra. ¡Saca el trasero aquí, ahora!",
  ui_story_5068_50680401_70_dialog_content = "¡No hay médico aquí! Pero si buscas una razón para ver a uno, ¡con gusto te la daré!",
  ui_story_5068_50680401_71_dialog_content = "¡Piérdete, escoria!",
  ui_story_5068_50680401_72_dialog_content = "¡Ay!",
  ui_story_5068_50680401_73_dialog_content = "¿Por qué esta loca muerde a todos los que ve?! ¡Menos mal que reaccioné rápido!",
  ui_story_5068_50680401_74_dialog_content = "¡¿Cómo te atreves a acercarte sigilosamente a nosotros?! ¡No somos un blanco fácil para nadie! ¡Mátalos, ahora!",
  ui_story_5068_50680401_75_dialog_content = "A ver cuál de nosotros termina muerto.",
  ui_story_5068_50680401_76_dialog_content = "¡Uh!",
  ui_story_5068_50680401_77_dialog_content = "¡¿Qué demonios?! ¡Esto es una locura! ¡Todos, saquen sus armas! ¡Rápido!!!",
  ui_story_5068_50680401_78_dialog_content = "<color=#e8d9bb>¡Bam! ¡Bam!</color>",
  ui_story_5068_50680401_79_dialog_content = "¡Ahhh!",
  ui_story_5068_50680401_80_dialog_content = "¡No dejes que ninguno de ellos se te escape!!!",
  ui_story_5068_50680401_81_dialog_content = "<size=45><color=#e8d9bb>¡Bam! ¡Bam! ¡Bam!</color></size>",
  ui_story_5068_50680401_82_dialog_content = "(¿Qué está pasando aquí... Cómo terminaron las cosas así?!)",
  ui_story_5068_50680401_83_dialog_content = "(La puerta está completamente bloqueada. No podría escapar aunque quisiera...)",
  ui_story_5068_50680401_84_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  ui_story_5068_50680401_85_dialog_content = "¡Vamos! ¡Contesta, Señora Sheol!",
  ui_story_5068_50680502_1_dialog_content = "¡Un montón de idiotas! Este tipo está con ustedes, ¿verdad? Si no quieren que le pase nada—",
  ui_story_5068_50680502_2_dialog_content = "Te dije que no estamos trabajando juntos...",
  ui_story_5068_50680502_3_dialog_content = "¿Esta mujer está loca? Escogió a un tipo al azar y afirmó que era uno de nuestros Lobos Negros. ¿Alguno de ustedes conoce a este tipo?",
  ui_story_5068_50680502_4_dialog_content = "No. ¿Lo conoces?",
  ui_story_5068_50680502_5_dialog_content = "Qué casualidad; yo tampoco lo conozco.",
  ui_story_5068_50680502_6_dialog_content = "¡Jajajajaja!",
  ui_story_5068_50680502_7_dialog_content = "¡Eso es lo que te he estado diciendo todo el tiempo! ¿¡Por qué no me crees?!",
  ui_story_5068_50680502_8_dialog_content = "Tenerme como rehén no les servirá de nada a ninguno de los dos, así que ¿podrían por favor alejar el cuchillo de mi cuello? Realmente podría lastimarme...",
  ui_story_5068_50680502_9_dialog_content = "¡Cállate! Aunque no estés aliado con estos tipos, sigues siendo basura a mis ojos.",
  ui_story_5068_50680502_10_dialog_content = "Solo déjalo ir. No queremos que ningún transeúnte inocente salga lastimado.",
  ui_story_5068_50680502_11_dialog_content = "Inocente es la última palabra que usaría para describir a este tipo.",
  ui_story_5068_50680502_12_dialog_content = "Pero si incluso el médico lo dice... Entonces considera esto tu día de suerte.",
  ui_story_5068_50680502_13_dialog_content = "¡Que quede claro! ¡Cualquiera que se meta con los Lobos Negros no acabará bien!",
  ui_story_5068_50680502_14_dialog_content = "Sabes, en realidad estábamos pensando en tomar pacíficamente todo este vecindario. Pero ahora, parece que aplastarlo es una mejor opción.",
  ui_story_5068_50680502_15_dialog_content = "...",
  ui_story_5068_50680502_16_dialog_content = "Entonces, ¿qué exactamente están haciendo ustedes idiotas aquí?",
  ui_story_5068_50680502_17_dialog_content = "¡Espera un minuto! ¡Te conozco! Eres—",
  ui_story_5068_50680502_18_dialog_content = "¡Eres Eleanor!",
  ui_story_5068_50680502_19_dialog_content = "...",
  ui_story_5068_50680502_20_dialog_content = "¡Así es! ¡Ahora recuerdo! ¡Te conozco!",
  ui_story_5068_50680502_21_dialog_content = "¿Eh? El... ¿qué? No me suena de nada.",
  ui_story_5068_50680502_22_dialog_content = "Eleanor! Quiero decir—",
  ui_story_5068_50680502_23_dialog_content = "Eh...",
  ui_story_5068_50680502_24_dialog_content = "Lo siento mucho...",
  ui_story_5068_50680502_25_dialog_content = "Pero si esto sigue así, solo vas a causarnos más problemas... No me dejaste otra opción...",
  ui_story_5068_50680502_26_dialog_content = "Uhh...",
  ui_story_5068_50680502_27_dialog_content = "Relájate, prometo que no dolerá mucho...",
  ui_story_5068_50680502_28_dialog_content = "¿¡Qué!? ¿¡Qué le hiciste!?",
  ui_story_5068_50680502_29_dialog_content = "No te preocupes, no tengo intención de quitarle la vida a nadie.",
  ui_story_5068_50680502_30_dialog_content = "Como puedes ver, acabo de dejarlo inconsciente.",
  ui_story_5068_50680502_31_dialog_content = "Esta, esta mujer, está loca... Retírate... Muévete, muévete!",
  ui_story_5068_50680502_32_dialog_content = "Regresa e informa a los jefes. ¡Que los superiores se enteren—",
  ui_story_5068_50680502_33_dialog_content = "¡¡¡Puaj!!!",
  ui_story_5068_50680502_34_dialog_content = "Lo siento, pero no puedo dejar que ninguno de ustedes escape.",
  ui_story_5068_50680502_35_dialog_content = "Si incluso uno de ustedes logra salir con sus recuerdos intactos... Me causará aún más problemas.",
  ui_story_5068_50680502_36_dialog_content = "Lo siento, señorita Rebecca. Ese chico debe haberme reconocido de mis días de vagabundeo...",
  ui_story_5068_50680502_37_dialog_content = "Está bien, Eleanor, sabía que este día llegaría tarde o temprano. Solo era cuestión de tiempo.",
  ui_story_5068_50680502_38_dialog_content = "(Todo lo que se necesitó fue un solo ataque...)",
  ui_story_5068_50680502_39_dialog_content = "(Parece que Rebecca no estaba luchando con toda su fuerza contra esos Lobos Negros.)",
  ui_story_5068_50680502_40_dialog_content = "(Ella parece tan frágil, pero en realidad es muy poderosa... No creo que sea solo una médica común.)",
  ui_story_5068_50680502_41_dialog_content = "En cuanto a ti, ten la seguridad de que no tengo intención de hacerte lo mismo... Al menos no ahora mismo.",
  ui_story_5068_50680502_42_dialog_content = "No necesitas preocuparte por estas personas tampoco.",
  ui_story_5068_50680502_43_dialog_content = "¿Recuerdas la inyección que iba a ponerte antes? Para decir la verdad, en realidad no era medicina.",
  ui_story_5068_50680502_44_dialog_content = "Señorita Rebecca? ¿No crees que le estás diciendo demasiado?",
  ui_story_5068_50680502_45_dialog_content = "No te preocupes. Sé lo que estoy haciendo.",
  ui_story_5068_50680502_46_dialog_content = "El suero en la inyección no es medicina, sino <color=#FFB400>veneno</color>... El mismo tipo que acabo de administrar a estas personas.",
  ui_story_5068_50680502_47_dialog_content = "¿Veneno?!",
  ui_story_5068_50680502_48_dialog_content = "Sí, veneno... Pero no es letal.",
  ui_story_5068_50680502_49_dialog_content = "Estas personas... simplemente están inconscientes, nada más.",
  ui_story_5068_50680502_50_dialog_content = "¡Cuando estos villanos despierten, olvidarán quiénes son y qué estaban haciendo!",
  ui_story_5068_50680502_51_dialog_content = "Lo siento, pequeño... ¿Te asustamos hace un momento?",
  ui_story_5068_50680502_52_dialog_content = "¡No tengo miedo en absoluto!",
  ui_story_5068_50680502_53_dialog_content = "Entonces, ¿te sientes mejor?",
  ui_story_5068_50680502_54_dialog_content = "¡Me siento mucho mejor ahora! ¡Gracias, Doctor!",
  ui_story_5068_50680502_55_dialog_content = "Bien... Pareces estar perfectamente bien, lo que significa que puedes irte a casa ahora.",
  ui_story_5068_50680502_56_dialog_content = "La clínica no es muy segura en este momento, así que hazme un favor y dile a todos que se mantengan alejados por ahora.",
  ui_story_5068_50680502_57_dialog_content = "Y recuerda mantener todo lo que pasó aquí en secreto, ¿entendido?",
  ui_story_5068_50680502_58_dialog_content = "¡Entendido! ¡Considérelo hecho!",
  ui_story_5068_50680502_59_dialog_content = "Entonces, ¡regresaré por ahora! ¡Adiós, Doctor! ¡Adiós, señorita Asistente!",
  ui_story_5068_50680502_60_dialog_content = "Eleanor... ¿Podrías por favor deshacerte de estas personas ahora?",
  ui_story_5068_50680502_61_dialog_content = "—!",
  ui_story_5068_50680502_62_dialog_content = "Por favor, no malinterpretes. Solo quiero que ella los lleve a un lugar seguro y lejos de aquí.",
  ui_story_5068_50680502_63_dialog_content = "¿Por qué le estás contando todo esto, señorita Rebecca? ¡Simplemente noquéalo para que pueda deshacerme de él junto con los demás!",
  ui_story_5068_50680502_64_dialog_content = "He cambiado de opinion.",
  ui_story_5068_50680502_65_dialog_content = "... No entiendo.",
  ui_story_5068_50680502_66_dialog_content = "No me di cuenta antes... ¿Quizás es porque hemos estado escondidos en esta pequeña clínica durante el último año?",
  ui_story_5068_50680502_67_dialog_content = "Los barrios bajos y esta clínica... Nos han brindado protección, pero también han limitado un poco nuestra perspectiva.",
  ui_story_5068_50680502_68_dialog_content = "No tenía idea de que todavía hubiera Caelestites en el mundo.",
  ui_story_5068_50680502_69_dialog_content = "...",
  ui_story_5068_50680502_70_dialog_content = "¿Celestitas? ¿Qué son esos?",
  ui_story_5068_50680502_71_dialog_content = "¿No te diste cuenta? O sea, ¿algo que no se sintió como de costumbre cuando estabas peleando?",
  ui_story_5068_50680502_72_dialog_content = "Supongo que se sintió un poco diferente...",
  ui_story_5068_50680502_73_dialog_content = "Sentí como si... ¡como si pudiera ver diferentes patrones de Lumina a mi alrededor! ¡Hizo que la lucha fuera aún más fluida de lo habitual!",
  ui_story_5068_50680502_74_dialog_content = "Entonces parece que no fue solo mi imaginación.",
  ui_story_5068_50680502_75_dialog_content = "Y si mi corazonada es correcta... Entonces eso te convierte en un Celestita, ¿no es así?",
  ui_story_5068_50680502_76_dialog_content = "Los únicos capaces de utilizar una técnica tan especial para ayudarnos en la batalla son los legendarios Celestitas.",
  ui_story_5068_50680502_77_dialog_content = "Mencionaste mi nombre accidentalmente antes, lo cual probablemente aprendiste a través de esas mismas habilidades, ¿verdad?",
  ui_story_5068_50680502_78_dialog_content = "Pareces saber mucho sobre los Celestitas.",
  ui_story_5068_50680502_79_dialog_content = "Solo por lo que he leído en libros sobre el pasado, tenía la impresión de que los Celestitas eran todos...",
  ui_story_5068_50680502_80_dialog_content = "Lo siento, simplemente... nunca esperé conocer a un Celestita así.",
  ui_story_5068_50680502_81_dialog_content = "Bueno, tienes razón. Mi nombre es PlayerName y realmente soy un Caelestita. ¿Quiénes son ustedes dos exactamente?",
  ui_story_5068_50680502_82_dialog_content = "Solo una <color=#FFB400>doctora sin nombre</color> y su <color=#FFB400>asistente sin nombre</color>. ¡Eso es todo lo que necesitas saber!",
  ui_story_5068_50680502_83_dialog_content = "Eleanor... PlayerName tuvo la amabilidad de presentarse, así que deberíamos hacer lo mismo por él.",
  ui_story_5068_50680502_84_dialog_content = "¡¿Señorita Rebecca?!",
  ui_story_5068_50680502_85_dialog_content = "Ese es mi nombre: Rebecca Svanedona. Y este es Eleanor.",
  ui_story_5068_50680502_86_dialog_content = "Por ciertas razones... Tuvimos que mantener nuestros nombres en secreto.",
  ui_story_5068_50680502_87_dialog_content = "Y aún así estabas dispuesto a compartirlas conmigo.",
  ui_story_5068_50680502_88_dialog_content = "Eso es porque creo que no nos quieres hacer daño.",
  ui_story_5068_50680502_89_dialog_content = "En los libros que leí, los Caelestites siempre fueron descritos como una raza amable y pacífica...",
  ui_story_5068_50680502_90_dialog_content = "Además... Parece que no tienes ninguna capacidad de combate, así que si actuaras en contra de nosotros, no tendría problemas en someterte. ¿No es cierto?",
  ui_story_5068_50680502_91_dialog_content = "(A pesar de lo suave que es su tono, no hay ni un ápice de compasión en sus palabras... Aunque me dijo su nombre, sigue siendo tan distante como antes.)",
  ui_story_5068_50680502_92_dialog_content = "¿Así que este tipo es aún más débil de lo que parece? Bien, eso es una cosa menos de qué preocuparse.",
  ui_story_5068_50680502_93_dialog_content = "Me voy a deshacer de la escoria que ensucia nuestro suelo.",
  ui_story_5068_50680502_94_dialog_content = "Juzgando por lo que dijeron antes, este lugar ya no es seguro. Es posible...",
  ui_story_5068_50680502_95_dialog_content = "Que tendremos que dejar atrás este lugar... Y todo Umbraton también.",
  ui_story_5068_50680502_96_dialog_content = "Si las cosas llegan a ese punto—",
  ui_story_5068_50680502_97_dialog_content = "No te preocupes... Haré planes para el peor de los casos.",
  ui_story_5068_50680502_98_dialog_content = "Además, deberías quedarte en la habitación oculta hasta que vuelva.",
  ui_story_5068_50680502_99_dialog_content = "No dejes entrar a nadie mientras no estoy.",
  ui_story_5068_50680601_1_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5068_50680601_2_dialog_content = "... Muy bien, ese debería ser el último de ellos.",
  ui_story_5068_50680601_3_dialog_content = "Silbido...",
  ui_story_5068_50680601_4_dialog_content = "¿Mmm? Despertándote ya, ¿eh?",
  ui_story_5068_50680601_5_dialog_content = "¡Tú... qué estás haciendo?!",
  ui_story_5068_50680601_6_dialog_content = "¿Eh? ¿Dónde está este basurero? ¡Chicos, despierten!",
  ui_story_5068_50680601_7_dialog_content = "... ¿Mmm?",
  ui_story_5068_50680601_8_dialog_content = "¿Qué... qué está pasando?!",
  ui_story_5068_50680601_9_dialog_content = "¡Todos, despierten! ¡Oye, oye! ¡Despierten ya!",
  ui_story_5068_50680601_10_dialog_content = "Mi cabeza... da vueltas. ¿Por qué no puedo recordar nada?",
  ui_story_5068_50680601_11_dialog_content = "... Este que está frente a nosotros debe saber algo.",
  ui_story_5068_50680601_12_dialog_content = "¡Habla! ¿Por qué te escabullías a nuestro alrededor justo ahora? ¿Quién está detrás de esto?!",
  ui_story_5068_50680601_13_dialog_content = "¿Eh? ¿Cómo están todos despiertos tan pronto?",
  ui_story_5068_50680601_14_dialog_content = "¿La señorita Rebecca les dio una dosis más baja para evitar efectos secundarios duraderos? Como siempre digo, ella es una persona demasiado amable...",
  ui_story_5068_50680601_15_dialog_content = "¿Qué estaba murmurando ella sola para sí misma?",
  ui_story_5068_50680601_16_dialog_content = "¿A quién le importa? ¡Vamos a agarrarla!",
  ui_story_5068_50680601_17_dialog_content = "Hmph. Odio decepcionarlos, pero ¡no soy ni de cerca tan amable como el médico!",
  ui_story_5068_50680602_1_dialog_content = "—?!",
  ui_story_5068_50680602_2_dialog_content = "No soy médico, así que discúlpame si me equivoco con la dosis.",
  ui_story_5068_50680602_3_dialog_content = "Pero te prometo que esta inyección te hará olvidar todo y tendrás una nueva vida. Dulces sueños, basura.",
  ui_story_5068_50680602_4_dialog_content = "¡¿Eh?!",
  ui_story_5068_50680602_5_dialog_content = "Eres el último.",
  ui_story_5068_50680602_6_dialog_content = "Por favor... Por favor, sólo déjame ir...",
  ui_story_5068_50680602_7_dialog_content = "¿Eh? Espera un segundo...",
  ui_story_5068_50680602_8_dialog_content = "Eleanor?",
  ui_story_5068_50680602_9_dialog_content = "Eleanor, ¡eres tú, verdad?! No, no me pongas esa inyección! ¡Sé que seré un caso perdido si lo haces!",
  ui_story_5068_50680602_10_dialog_content = "No depende de ti.",
  ui_story_5068_50680602_11_dialog_content = "¡No lo hagas! Te lo ruego, Eleanor! Por los viejos tiempos, ¡por favor perdona a tu amigo!",
  ui_story_5068_50680602_12_dialog_content = "¡Te he cuidado tanto en <color=#FFB400>todos esos años</color>!",
  ui_story_5068_50680602_13_dialog_content = "Ya conoces las reglas, así que solo responde algunas de mis preguntas.",
  ui_story_5068_50680602_14_dialog_content = "¡Por supuesto! ¡Lo que quieras! Solo promete dejarme ir y te contaré todo lo que sé.",
  ui_story_5068_50680602_15_dialog_content = "¿Qué te enviaron a hacer?",
  ui_story_5068_50680602_16_dialog_content = "... ¿Para qué me enviaron hoy? Yo...",
  ui_story_5068_50680602_17_dialog_content = "¿No puedes recordar, eh?",
  ui_story_5068_50680602_18_dialog_content = "N-No, ¡no es eso! ¡Solo dame un minuto! No, ¡treinta segundos!",
  ui_story_5068_50680602_19_dialog_content = "...¡Recuerdo! ¡Finalmente lo recuerdo ahora!",
  ui_story_5068_50680602_20_dialog_content = "Nosotros... Nos enviaron aquí para probar un nuevo desarrollo...",
  ui_story_5068_50680602_21_dialog_content = "...",
  ui_story_5068_50680602_22_dialog_content = "Si no puedes decírmelo, no te obligaré a hacerlo.",
  ui_story_5068_50680602_23_dialog_content = "La <color=#FFB400>niebla negra</color>.",
  ui_story_5068_50680602_24_dialog_content = "Nosotros... Nos enviaron aquí para probar los efectos de una niebla negra recién desarrollada, y también...",
  ui_story_5068_50680602_25_dialog_content = "Para encontrar a un médico que pueda tratar sus efectos, al parecer, el <color=#FFB400>Director</color> está extremadamente interesado en esta persona...",
  ui_story_5068_50680602_26_dialog_content = "¿Una prueba? ¿De un nuevo tipo de niebla negra?!",
  ui_story_5068_50680602_27_dialog_content = "Sí... Y fue entonces cuando escuchamos sobre un médico sospechoso en el subsuelo. De hecho, estoy bastante seguro de que estábamos en camino para buscar a ese médico... Entonces, ¿qué estamos haciendo aquí?",
  ui_story_5068_50680602_28_dialog_content = "¡Espera!",
  ui_story_5068_50680602_29_dialog_content = "¿Qué estás haciendo aquí también? Y tú, ¿qué estás—",
  ui_story_5068_50680602_30_dialog_content = "Lo siento... Hermano.",
  ui_story_5068_50680602_31_dialog_content = "Ahora recuerdas un poco demasiado.",
  ui_story_5068_50680602_32_dialog_content = "<color=#e8d9bb>susurro, susurro...</color>",
  ui_story_5068_50680602_33_dialog_content = "Bul—Bul—",
  ui_story_5068_50680701_1_dialog_content = "<color=#e8d9bb>Tic-tac... Tic-tac...</color>",
  ui_story_5068_50680701_2_dialog_content = "Un momento, por favor.",
  ui_story_5068_50680701_3_dialog_content = "<color=#e8d9bb>Clic, clic.</color>",
  ui_story_5068_50680701_4_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5068_50680701_5_dialog_content = "Ahí. Si quieres saber más sobre la niebla negra, por favor ven conmigo.",
  ui_story_5068_50680701_6_dialog_content = "Pero primero, debo pedir... Que mantengas en secreto todo lo que veas y escuches en esta habitación oculta.",
  ui_story_5068_50680701_7_dialog_content = "Por supuesto, lo prometo.",
  ui_story_5068_50680701_8_dialog_content = "Por favor, cuida tus pasos...",
  ui_story_5068_50680701_9_dialog_content = "Ya estamos acá.",
  ui_story_5068_50680701_10_dialog_content = "—¡¡!",
  ui_story_5068_50680701_11_dialog_content = "¡Hay... Hay tantos frascos y botellas aquí!",
  ui_story_5068_50680701_12_dialog_content = "Los he estado acumulando durante mucho tiempo sin darme cuenta. Antes de que me diera cuenta, la habitación estaba llena de especímenes.",
  ui_story_5068_50680701_13_dialog_content = "No me digas que estos son todos los...",
  ui_story_5068_50680701_14_dialog_content = "Algunos sí y otros no. Incluso hay varios que tienen efectos completamente diferentes.",
  ui_story_5068_50680701_15_dialog_content = "Estos frascos y botellas contienen los frutos de mi investigación. Al usar mi poder en <color=#FFB400>diferentes tipos de Lumina</color>, puedo producir todo tipo de sueros con una amplia variedad de efectos.",
  ui_story_5068_50680701_16_dialog_content = "¿<color=#FFB400>Diferentes tipos de Lumina</color>?",
  ui_story_5068_50680701_17_dialog_content = "Como probablemente ya sabes, esta clínica funciona en las barriadas pobres. No todos los que vienen aquí pueden pagar su tratamiento o medicamentos con dinero.",
  ui_story_5068_50680701_18_dialog_content = "Entonces, para aquellos pacientes con Lumina fuerte y billeteras vacías, les ofrezco la opción de pagar mis servicios con su Lumina.",
  ui_story_5068_50680701_19_dialog_content = "¿Estás familiarizado con este tipo de situación? Cuando se trata de investigación, no hay nada más importante que tener suficientes especímenes y materiales a mano.",
  ui_story_5068_50680701_20_dialog_content = "No te preocupes, nunca he obligado a nadie a cumplir con mi trabajo. Por favor, confía en mí cuando digo que toda esta Lumina fue proporcionada voluntariamente por mis pacientes o sus familiares.",
  ui_story_5068_50680701_21_dialog_content = "La Lumina que recojo cada vez es también muy pequeña y no resultará en efectos negativos a largo plazo para los Aurorianos.",
  ui_story_5068_50680701_22_dialog_content = "Pero, ¿qué investigas exactamente que requiera tanta Lumina?",
  ui_story_5068_50680701_23_dialog_content = "Si es para hacer y vender más cosas como ese veneno de pérdida de memoria... No puedo evitar sentirme preocupado por esto.",
  ui_story_5068_50680701_24_dialog_content = "Lamento haberte dado esa impresión. Debes pensar... ¿Que estoy tramando algo terrible, verdad?",
  ui_story_5068_50680701_25_dialog_content = "Todo lo que sé es que eres un buen médico cuando estás con tus pacientes. No se puede negar eso.",
  ui_story_5068_50680701_26_dialog_content = "Pero aún tengo curiosidad por conocer el objetivo de tu \"investigación.\"",
  ui_story_5068_50680701_27_dialog_content = "El objetivo de mi investigación...",
  ui_story_5068_50680701_28_dialog_content = "Como Caelestite, deberías poder usar tus poderes especiales para leer mi mente, ¿verdad?",
  ui_story_5068_50680701_29_dialog_content = "Mis \"poderes especiales\" en realidad son una especie de habilidad psíquica. Solo puedo usarlos en situaciones peligrosas.",
  ui_story_5068_50680701_30_dialog_content = "Habilidades psíquicas... ya veo. ¿Se pueden usar para algo más? Como inmovilizar a otros, por ejemplo?",
  ui_story_5068_50680701_31_dialog_content = "Nada de eso, no. Aparte de permitirme pilotar mi Colossus y dirigir a otros en la batalla... Realmente no se pueden usar para nada más.",
  ui_story_5068_50680701_32_dialog_content = "¿Tu Colossus? Sí, parece que recuerdo algo sobre los Celestitas teniendo vehículos con ese nombre.",
  ui_story_5068_50680701_33_dialog_content = "Soroz no es solo un vehículo; es mi amigo más cercano e importante.",
  ui_story_5068_50680701_34_dialog_content = "¿\"Soroz\"? ¿Es así como llamas a tu Coloso? Qué nombre tan impresionante...",
  ui_story_5068_50680701_35_dialog_content = "Si alguna vez tienes tiempo, me encantaría presentarte a Soroz algún día. Muchos de nuestros amigos vienen a bordo para pasar el rato todo el tiempo.",
  ui_story_5068_50680701_36_dialog_content = "Oh... Tal vez algún día, claro...",
  ui_story_5068_50680701_37_dialog_content = "Gracias por compartir tanto sobre ti y los Celestitas... Supongo que también debería compartir algunos secretos sobre mí.",
  ui_story_5068_50680701_38_dialog_content = "La niebla negra, para empezar.",
  ui_story_5068_50680701_39_dialog_content = "Esta neblina negra... es mi familia.",
  ui_story_5068_50680701_40_dialog_content = "... ¿Tu familia?",
  ui_story_5068_50680701_41_dialog_content = "¿Quieres decir que usaste la Lumina de tu familia para hacerlo...?",
  ui_story_5068_50680701_42_dialog_content = "No. Esta niebla negra es el método único de... existir de la <color=#FFB400>Familia Svanedona</color>.",
  ui_story_5068_50680701_43_dialog_content = "Quizás no lo sepas, pero hasta hace un año, la familia Svanedona era una de las más prominentes y adineradas en todo Umbraton.",
  ui_story_5068_50680701_44_dialog_content = "Esta familia tiene una habilidad única que se transmite de generación en generación: el poder de crear <color=#FFB400>sueros</color> curativos con su Lumina.",
  ui_story_5068_50680701_45_dialog_content = "Y resulta que soy uno de sus miembros.",
  ui_story_5068_50680701_46_dialog_content = "Además de crear sueros médicos, también soy capaz de producir un tipo de <color=#FFB400>veneno</color> altamente peligroso. Si es un gen recesivo o un regalo divino, nadie lo sabe, aunque mi familia prefiere mucho la última explicación.",
  ui_story_5068_50680701_47_dialog_content = "En el pasado, desconocía por completo los usos de este veneno y sus implicaciones. Después de todo, siempre preferí usar mis poderes para sanar a las personas, pero entonces...",
  ui_story_5068_50680701_48_dialog_content = "...",
  ui_story_5068_50680701_49_dialog_content = "¿Qué está pasando? ¿Dónde estoy?",
  ui_story_5068_50680701_50_dialog_content = "Rebecca? Rebecca! ¿Estás ahí?",
  ui_story_5068_50680701_51_dialog_content = "Estoy aquí, PlayerName. Por favor, no tengas miedo, solo estoy usando la niebla para recrear mis recuerdos de ese día...",
  ui_story_5068_50680701_52_dialog_content = "Mirar...",
  ui_story_5068_50680701_53_dialog_content = "La persona en el suelo es mi tío Albert. A él le gustaba especialmente abrazarme cuando era pequeño, pero no soportaba la sensación de picazón de su barba.",
  ui_story_5068_50680701_54_dialog_content = "La niña sentada allí es mi prima Jessica. Siempre fue una niña muy linda; recuerdo que llevaba una muñeca a dondequiera que iba, y era igual de linda que ella. A mi hermana mayor Isa también le encantaba mucho.",
  ui_story_5068_50680701_55_dialog_content = "Isa... mi hermana, también amaba comprarme cosas caras todo el tiempo, aunque no tuviera uso para la mayoría de ellas. Ese día, ni siquiera tuve la oportunidad de ver su rostro una última vez.",
  ui_story_5068_50680701_56_dialog_content = "Y allá... está mi madre Lillian. La extraño mucho. Los guisos que preparaba, el calor de su abrazo y la sonrisa en su rostro cuando me decía que me amaba.",
  ui_story_5068_50680701_57_dialog_content = "Pero ya no son parte de este mundo ahora.",
  ui_story_5068_50680701_58_dialog_content = "Si Eleanor no me hubiera rescatado en aquel entonces, probablemente me habría convertido en la niebla negra, igual que ellos.",
  ui_story_5068_50680701_59_dialog_content = "La niebla negra... Pero, ¿no dijiste que era su forma única de existir?",
  ui_story_5068_50680701_60_dialog_content = "Así es. Cuando un miembro de la Familia Svanedona muere y el Lumina abandona completamente su cuerpo, el suero curativo que solían producir se deteriora y se convierte en una sustancia venenosa.",
  ui_story_5068_50680701_61_dialog_content = "Y si ese veneno entra en contacto con un fuego lo suficientemente caliente...",
  ui_story_5068_50680701_62_dialog_content = "Se convierte en una niebla negra que puede bloquear el cielo.",
  ui_story_5068_50680701_63_dialog_content = "A veces me preguntaba por qué nací con la habilidad de producir este veneno...",
  ui_story_5068_50680701_64_dialog_content = "Cuando mi familia fue atacada por los <color=#FFB400>Lobos Negros</color>, me di cuenta dolorosamente de lo completamente impotente que era para protegerlos.",
  ui_story_5068_50680701_65_dialog_content = "Fue el momento más bajo y desesperanzador de mi vida.",
  ui_story_5068_50680701_66_dialog_content = "Entonces, ustedes dos se han estado escondiendo de los Lobos Negros todo el tiempo, ¿eh...",
  ui_story_5068_50680701_67_dialog_content = "Permítame responder a su pregunta anterior. Durante el último año, he estado investigando cómo utilizar adecuadamente mi veneno...",
  ui_story_5068_50680701_68_dialog_content = "Solo tengo un objetivo: proteger a la persona que me importa.",
  ui_story_5068_50680701_69_dialog_content = "Y eso sería Eleanor, ¿verdad?",
  ui_story_5068_50680701_70_dialog_content = "Sí... Ella es todo lo que me queda ahora.",
  ui_story_5068_50680701_71_dialog_content = "Pero la niebla negra en tu mano...",
  ui_story_5068_50680701_72_dialog_content = "Estoy seguro de que fue creado por un miembro de la familia Svanedona que tuvo un final prematuro. ¡Además, fue creado hace poco tiempo!",
  ui_story_5068_50680701_73_dialog_content = "En otras palabras...",
  ui_story_5068_50680701_74_dialog_content = "Tengo una propuesta para ti, PlayerName...",
  ui_story_5068_50680701_75_dialog_content = "Sé lo que estás pensando. Es posible que algunos de tus familiares hayan sobrevivido al ataque del año pasado y que los Lobos Negros los estén explotando en este momento...",
  ui_story_5068_50680701_76_dialog_content = "Parece que mi investigación está avanzando después de todo.",
  ui_story_5068_50680701_77_dialog_content = "No te preocupes, aunque mi trabajo sea investigar la niebla negra, definitivamente te ayudaré a buscar señales de tu familia.",
  ui_story_5068_50680701_78_dialog_content = "Gracias, PlayerName...",
  ui_story_5068_50680801_1_dialog_content = "Bul—Bul—",
  ui_story_5068_50680801_2_dialog_content = "¡Busquen cuidadosamente en el área donde el Equipo B realizó sus experimentos! ¡Su desaparición no fue un accidente!",
  ui_story_5068_50680801_3_dialog_content = "¡No dejemos piedra sin remover! Nadie descansa hasta que encontremos a los culpables detrás de esto.",
  ui_story_5068_50680801_4_dialog_content = "¡Sí, Director!",
  ui_story_5068_50680801_5_dialog_content = "¿Fuiste tú, Rebecca? Incluso después de un año entero... ¿Sigues merodeando en Umbraton? ¿Realmente crees que puedes mirarme así desde arriba? O tal vez...",
  ui_story_5068_50680801_6_dialog_content = "¿Mmm?",
  ui_story_5068_50680801_7_dialog_content = "<color=#e8d9bb>Tic-tac... Tic-tac...</color>",
  ui_story_5068_50680801_8_dialog_content = "Tres... no, cinco de ellos... Tal vez incluso más. Siguen siguiéndome y no puedo deshacerme de ellos.",
  ui_story_5068_50680801_9_dialog_content = "Parece que uno de esos payasos logró pedir refuerzos después de todo...",
  ui_story_5068_50680801_10_dialog_content = "¡Atrévanse, cobardes! ¡Salgan y luchen!",
  ui_story_5068_50680802_1_dialog_content = "Espera... ¡Alto! ¡Deténganse todos!",
  ui_story_5068_50680802_2_dialog_content = "¿Crees que voy a parar solo porque lo pediste?!",
  ui_story_5068_50680802_3_dialog_content = "Abre los ojos, Eleanor! Soy yo, Isa! ¿No me digas que te olvidaste de mí?!",
  ui_story_5068_50680802_4_dialog_content = "Isa...?",
  ui_story_5068_50680802_5_dialog_content = "¡Estás... Estás todavía vivo?!",
  ui_story_5068_50680802_6_dialog_content = "¡No por mucho tiempo, si no dejas de atacarme!",
  ui_story_5068_50680802_7_dialog_content = "¿Eleanor? ¿Qué está pasando aquí afuera? Escuché peleas, así que yo...",
  ui_story_5068_50680802_8_dialog_content = "—!!!",
  ui_story_5068_50680802_9_dialog_content = "Es... realmente eres tú...",
  ui_story_5068_50680802_10_dialog_content = "Rebecca—!",
  ui_story_5068_50680802_11_dialog_content = "¡Te he estado buscando por todas partes durante el último año!",
  ui_story_5068_50680802_12_dialog_content = "Gracias a Dios... ¡Gracias a Dios que sigues vivo! ¡Estoy tan feliz de haberte encontrado por fin!",
  ui_story_5068_50680802_13_dialog_content = "... <color=#FFB400>Isa</color>?!",
  ui_story_5068_50680802_14_dialog_content = "No... Debe ser un sueño...",
  ui_story_5068_50680802_15_dialog_content = "¡Esto no es un sueño, Rebecca!",
  ui_story_5068_50680802_16_dialog_content = "Pero pensé que también te perdí ese día...",
  ui_story_5068_50680802_17_dialog_content = "Bueno, como puedes ver, ¡estoy perfectamente bien! Tú, por otro lado... Has pasado por mucho, ¿verdad?",
  ui_story_5068_50680802_18_dialog_content = "(¿Isa? ¿No es la hermana mayor de Rebecca? ¿Podría ser realmente una coincidencia?)",
  ui_story_5068_50680802_19_dialog_content = "(También... ¿Estoy imaginando cosas? Parece que el veneno alrededor de Rebecca se debilita a medida que Isa se acerca a ella.)",
  ui_story_5068_50680802_20_dialog_content = "Y tú debes ser PlayerName, ¿verdad?",
  ui_story_5068_50680802_21_dialog_content = "Gracias a la información que proporcionaste, finalmente pude encontrar a mi hermana aquí... ¡Realmente no puedo agradecerte lo suficiente!",
  ui_story_5068_50680802_22_dialog_content = "Pero no recuerdo haberte dado—Espera, ¿podría haber sido la Señora Sheol?!",
  ui_story_5068_50680802_23_dialog_content = "¡Sí! Lady Sheol recibió tus mensajes y grabaciones de antes, pero no ha podido contactarte desde entonces.",
  ui_story_5068_50680802_24_dialog_content = "¡Vaya, no es broma! ¡Mi terminal está llena de mensajes de ella! Debió haber sido tal el caos que olvidé revisar...",
  ui_story_5068_50680802_25_dialog_content = "¡Así que tú eres el asistente que la Señora Sheol envió aquí?!",
  ui_story_5068_50680802_26_dialog_content = "¡Así es! Actualmente estoy trabajando para la Señora Sheol y el Gremio de Explorador Nublar.",
  ui_story_5068_50680802_27_dialog_content = "Hace un tiempo, supe que los Lobos Negros buscaban a una chica que pudiera tratar los efectos venenosos de la niebla negra...",
  ui_story_5068_50680802_28_dialog_content = "Lo que me llevó a suponer que mi hermana todavía estaba viva en algún lugar. Fue entonces cuando le pedí a Lady Sheol que me ayudara a estar alerta.",
  ui_story_5068_50680802_29_dialog_content = "He estado ayudándola a cobrar deudas durante los últimos días, pero cuando escuché sobre la niebla negra, regresé lo más rápido que pude.",
  ui_story_5068_50680802_30_dialog_content = "Tan pronto como llegué, Lady Sheol me dijo que alguien llamado PlayerName había contactado con un médico clandestino, y que probablemente era mi hermana Rebecca. Incluso si no fuera ella, la persona aún estaba estrechamente vinculada a la Familia Svanedona...",
  ui_story_5068_50680802_31_dialog_content = "¡Así que reuní a mi equipo y nos apresuramos a venir aquí de inmediato!",
  ui_story_5068_50680802_32_dialog_content = "¿Tu... equipo?",
  ui_story_5068_50680802_33_dialog_content = "¡Jeje! El Gremio Cloudrover fue lo suficientemente amable como para—",
  ui_story_5068_50680802_34_dialog_content = "Deberíamos continuar esta conversación dentro de la clínica. No es seguro aquí afuera en este momento, y también está el asunto de lo que pasó antes...",
  ui_story_5068_50680802_35_dialog_content = "¿No es seguro, dices? ¿Y qué pasó antes?",
  ui_story_5068_50680802_36_dialog_content = "Todo está bien ahora, Isa. Vamos a entrar.",
  ui_story_5068_50680802_37_dialog_content = "¿Eh? ¡Vale, seguro!",
  ui_story_5068_50680802_38_dialog_content = "¡Ey! ¡Vigila de cerca la clínica y los alrededores! ¡Nadie entra a menos que yo dé la orden!",
  ui_story_5068_50680802_39_dialog_content = "¡Entendido!",
  ui_story_5068_50680901_1_dialog_content = "... Si no hubiera actuado como un niño terco con nuestro papá ese día, nunca me habría marchado furioso de la casa.",
  ui_story_5068_50680901_2_dialog_content = "Pero en el momento en que me fui, nuestra casa fue atacada...",
  ui_story_5068_50680901_3_dialog_content = "Realmente no sabía qué hacer por mi cuenta. Intenté contactar a algunos de nuestros viejos conocidos, ¡pero terminé siendo traicionado por unos traidores podridos!",
  ui_story_5068_50680901_4_dialog_content = "¿¡Agotado...?!",
  ui_story_5068_50680901_5_dialog_content = "Mirando hacia atrás, fue mi culpa por ser tan descuidado. Cuando finalmente me di cuenta, ya me habían rodeado... Me hicieron pasar un infierno después de eso, pero afortunadamente Lady Sheol apareció un día.",
  ui_story_5068_50680901_6_dialog_content = "¡Ella es una persona increíble! No solo me salvó, sino que también me dio un trabajo... ¡Por eso quiero devolverle el favor trabajando lo más duro posible para ella!",
  ui_story_5068_50680901_7_dialog_content = "No tenía idea de que pasaste por tanto en solo un año...",
  ui_story_5068_50680901_8_dialog_content = "¡Jajaja! Todo eso ya quedó en el pasado, así que no te preocupes. Además, ¿no dije que estoy perfectamente bien ahora?",
  ui_story_5068_50680901_9_dialog_content = "Para mí, es como—¿Cómo debería decirlo? ¡Oh, cierto! ¡Tuve que crear mi propia suerte!",
  ui_story_5068_50680901_10_dialog_content = "Pero hablemos de ti, Rebecca! ¿Cómo terminaste en un lugar como este?",
  ui_story_5068_50680901_11_dialog_content = "Todo está completamente deteriorado por aquí. ¿Qué hace la hermanita más linda del mundo corriendo por los barrios bajos?",
  ui_story_5068_50680901_12_dialog_content = "Eleanor! Como la sirvienta de Rebecca, ¿no deberías cuidarla mejor?",
  ui_story_5068_50680901_13_dialog_content = "¡Por supuesto que he estado cuidando bien de ella! ¿Cómo podría hacerlo de otra manera?!",
  ui_story_5068_50680901_14_dialog_content = "Rebecca es la persona más importante del mundo para mí. Incluso si me costara la vida, lo haría—",
  ui_story_5068_50680901_15_dialog_content = "Entonces, ¿por qué no han encontrado un lugar mejor para que ella viva? ¡Este lugar es absolutamente inaceptable!",
  ui_story_5068_50680901_16_dialog_content = "Isa, sé que solo te preocupas por mí... Pero por favor, no la culpes.",
  ui_story_5068_50680901_17_dialog_content = "Ella ya no es sirvienta de la familia Svanedona, y... nosotras tampoco somos hijas de nobles ya.",
  ui_story_5068_50680901_18_dialog_content = "Si no fuera por Eleanor, yo habría... En cualquier caso, ella me rescató y ha estado haciendo todo lo posible para mantenerme a salvo de los Lobos Negros durante el último año.",
  ui_story_5068_50680901_19_dialog_content = "No fue fácil para ella encontrar esta clínica \"deteriorada\" y arreglarla tampoco.",
  ui_story_5068_50680901_20_dialog_content = "Puede que no sea el más lujoso, pero nos protege de los elementos.",
  ui_story_5068_50680901_21_dialog_content = "Vivimos como médico y asistente aquí, y valoro la nueva vida que hemos construido juntos.",
  ui_story_5068_50680901_22_dialog_content = "Señorita Rebecca...",
  ui_story_5068_50680901_23_dialog_content = "Además, vivir aquí no es tan malo.",
  ui_story_5068_50680901_24_dialog_content = "Cuando no tenemos tantos pacientes, cultivamos flores y hacemos artesanías como solíamos hacer...",
  ui_story_5068_50680901_25_dialog_content = "¿Ves? Eleanor hizo estos pendientes para mí con sus propias manos!",
  ui_story_5068_50680901_26_dialog_content = "Se ven bastante promedio... Eh, quiero decir, si fuera yo, te habría hecho un conjunto aún más bonito.",
  ui_story_5068_50680901_27_dialog_content = "Solía comprarte cosas todo el tiempo. Si alguien sabe lo que más te conviene, ¡soy yo!",
  ui_story_5068_50680901_28_dialog_content = "...",
  ui_story_5068_50680901_29_dialog_content = "Sí, sí, lo sé. Realmente tienes buen ojo para este tipo de cosas.",
  ui_story_5068_50680901_30_dialog_content = "*Tose*",
  ui_story_5068_50680901_31_dialog_content = "¿Mmm? ¿Tienes algo que decir, PlayerName?",
  ui_story_5068_50680901_32_dialog_content = "¡N-No realmente! Solo parece que Rebecca es la hermana mayor aquí...",
  ui_story_5068_50680901_33_dialog_content = "¿Eh? ¿Por qué todos siguen diciendo eso? Incluso nuestros familiares solían...",
  ui_story_5068_50680901_34_dialog_content = "... Isa, ¿crees que alguno de nuestros familiares todavía esté por ahí?",
  ui_story_5068_50680901_35_dialog_content = "Iba a hacerte exactamente la misma pregunta. Parece que ninguno de los dos sabe, ¿eh?",
  ui_story_5068_50680901_36_dialog_content = "Lady Sheol me dio una identidad falsa, así que los Lobos Negros no han podido encontrarme... Solo he oído que intentan cazarte a ti, no a ninguno de nuestros otros familiares.",
  ui_story_5068_50680901_37_dialog_content = "Tenía la impresión de que todos se habían perdido en el ataque del año pasado. No fue hasta que PlayerName me mostró esa botella de niebla negra que me di cuenta de que alguien de nuestra familia había sido afectado recientemente...",
  ui_story_5068_50680901_38_dialog_content = "Todavía... eso también significa que podría haber otras Svanedonas por ahí, ¿verdad?",
  ui_story_5068_50680901_39_dialog_content = "También es posible que estén huyendo de los Lobos Negros, igual que nosotros. Algunos de ellos podrían haber sido capturados y explotados también...",
  ui_story_5068_50680901_40_dialog_content = "No te preocupes, Rebecca. ¡Te prometo que te ayudaré a encontrarlos sin importar qué!",
  ui_story_5068_50680901_41_dialog_content = "Antes de continuar con nuestra investigación, sugiero que cambiemos de ubicación lo más pronto posible. La clínica ya no es segura.",
  ui_story_5068_50680901_42_dialog_content = "Los Lobos Negros... Incluso después de atacar a toda nuestra familia hace un año, ¿todavía no han abandonado la caza? ¿Qué podrían querer de nosotros?",
  ui_story_5068_50680901_43_dialog_content = "Si la Señora Sheol no me hubiera detenido, ¡ya habría ido a ajustar cuentas con ellos!",
  ui_story_5068_50680901_44_dialog_content = "Puede que no conozca a esta \"Lady Sheol\" de la que sigues hablando, pero creo que tiene la idea correcta. Enfrentarse a los Lobos Negros tú solo es increíblemente peligroso.",
  ui_story_5068_50680901_45_dialog_content = "Pero, ¿y ahora? Te tengo a ti, así como a muchas personas en el Gremio de Explorador Nublar para ayudarme. Tarde o temprano, voy a cobrar la deuda que los Lobos Negros le deben a la Familia Svanedona.",
  ui_story_5068_50680901_46_dialog_content = "¡Así es! Si necesitas un nuevo lugar para esconderte de los Lobos Negros, ¿por qué no vienes al Gremio de Explorador Nublar conmigo?",
  ui_story_5068_50680901_47_dialog_content = "¡Creo que es una gran idea!",
  ui_story_5068_50680901_48_dialog_content = "La Señora Sheol es quien me contrató para esto, y todos aquí están estrechamente relacionados con la niebla negra. Estoy seguro de que ella te ofrecerá la mejor protección que el gremio pueda comprar.",
  ui_story_5068_50680901_49_dialog_content = "Pero...",
  ui_story_5068_50680901_50_dialog_content = "¿Mmm? ¿Tienes algo en mente, Rebecca?",
  ui_story_5068_50680901_51_dialog_content = "Estoy seguro de que le preocupa involucrar a Lady Sheol y al Gremio de Explorador Nublar en nuestros problemas... Así como a ti, Isa.",
  ui_story_5068_50680901_52_dialog_content = "¿Qué? ¡Pero somos familia! Nunca me molestaría algo así, ¡y tampoco lo haría Lady Sheol! Ella es una buena persona, estoy seguro de que no le importará.",
  ui_story_5068_50680901_53_dialog_content = "No importa cuán feroces sean los Lobos Negros, sería una locura enfrentarse al Gremio Cloudrover. Cuando llegue el momento adecuado, podemos usar el poder del gremio para aplastarlos y vengar a nuestra familia.",
  ui_story_5068_50680901_54_dialog_content = "Venganza... Nunca es tan simple. Solo quiero seguir viviendo en paz... contigo y Eleanor a mi lado.",
  ui_story_5068_50680901_55_dialog_content = "Lo sé, Rebecca, pero el mundo no es tan simple.",
  ui_story_5068_50680901_56_dialog_content = "Sé que no quieres lastimar a nadie, ¡pero eso no les importa! ¡La gente encontrará todo tipo de razones para hacerte daño!",
  ui_story_5068_50680901_57_dialog_content = "Nunca quise mostrarte la crueldad de nuestro mundo, pero independientemente de lo que queramos, ¡necesitamos enfrentar la realidad de frente ahora mismo!",
  ui_story_5068_50680901_58_dialog_content = "Es totalmente irrazonable, ¿verdad?",
  ui_story_5068_50680901_59_dialog_content = "Pero así son las cosas: los fuertes se comen a los débiles y solo los más aptos sobreviven. Si no hacemos el primer movimiento—",
  ui_story_5068_50680901_60_dialog_content = "¡Basta ya! No hay necesidad de seguir acosándola con esto.",
  ui_story_5068_50680901_61_dialog_content = "Siempre ha sido una persona amable y gentil. ¡Mientras pueda seguir siendo así, me encargaré de todo lo demás yo mismo!",
  ui_story_5068_50680901_62_dialog_content = "¿Tú? ¡Pero hay un límite en lo que puedes hacer! ¡Algunas cosas deben ser decididas por ella y nadie más! ¡No puedes esperar estar a su lado cada minuto de cada día!",
  ui_story_5068_50680901_63_dialog_content = "¡Puedo y lo haré! ¡Eso es exactamente lo que he estado haciendo durante el último año!",
  ui_story_5068_50680901_64_dialog_content = "¡Cálmense todos! Ahora no es el momento de discutir...",
  ui_story_5068_50680901_65_dialog_content = "Todavía creo que Isa tiene la idea correcta, Rebecca: si te preocupa tu seguridad, el Gremio de Explorador Nublar es un buen lugar para establecer campamento.",
  ui_story_5068_50680901_66_dialog_content = "¿Qué opinas, Eleanor?",
  ui_story_5068_50680901_67_dialog_content = "Iré con lo que decidas, señorita Rebecca.",
  ui_story_5068_50680901_68_dialog_content = "Ya veo... No hay tiempo para dudar, así que parece que tendremos que depender del Gremio Cloudrover por el momento.",
  ui_story_5068_50680901_69_dialog_content = "¡Bien! Ahora que hemos decidido, ¡pongámonos en marcha de inmediato!",
  ui_story_5068_50680901_70_dialog_content = "Solo necesito un momento para recoger algunas cosas. Échame una mano, Eleanor.",
  ui_story_5068_50680901_71_dialog_content = "Sí, señorita Rebecca.",
  ui_story_5068_50680901_72_dialog_content = "Entonces déjame—",
  ui_story_5068_50680901_73_dialog_content = "Eleanor es más que suficiente ayuda, Isa. Ella está familiarizada con las cosas que necesito, así que por favor... Solo ponte cómodo por ahora.",
  ui_story_5068_50680901_74_dialog_content = "Eleanor de nuevo... Hmph. ¿Qué podría saber ella sobre Rebecca que su propia hermana no sepa?!",
  ui_story_5068_50680901_75_dialog_content = "¡Oye! ¿Quién eres y qué asunto tienes aquí?!",
  ui_story_5068_50680901_76_dialog_content = "¿Eh? ¿Qué pasa con el alboroto repentino afuera?",
  ui_story_5068_50680901_77_dialog_content = "¡Ey! ¿¡Qué está pasando ahí fuera!?",
  ui_story_5068_50680901_78_dialog_content = "*Tosiendo* Urgh—Es... ¡Es la niebla negra! ¡Alguien la liberó en el aire!",
  ui_story_5068_50680901_79_dialog_content = "¡Esto es malo! ¡Vamos a verlo!",
  ui_story_5068_50680901_80_dialog_content = "¿Quién podría haber liberado tanta niebla negra por aquí...",
  ui_story_5068_50680901_81_dialog_content = "¿Fueron los Lobos Negros?!",
  ui_story_5068_50680901_82_dialog_content = "*Tosiendo* ¡Se siente horrible...!",
  ui_story_5068_50680901_83_dialog_content = "¡Por aquí, todos! ¡Rápido!",
  ui_story_5068_50680901_84_dialog_content = "Rebecca? ¿Cuándo saliste?",
  ui_story_5068_50680901_85_dialog_content = "Escuché una conmoción afuera hace un momento. Aquí, este suero debería reducir en gran medida los efectos de la niebla negra. ¡Todos, vengan aquí y tomen un poco para ustedes mismos!",
  ui_story_5068_50680901_86_dialog_content = "¡Objetivo localizado!",
  ui_story_5068_50680901_87_dialog_content = "¡...!",
  ui_story_5068_50680901_88_dialog_content = "¡Lárgate! ¡No dejaré que ninguno de ustedes ponga un dedo en la señorita Rebecca!",
  ui_story_5068_50680902_1_dialog_content = "¿Están todos bien?",
  ui_story_5068_50680902_2_dialog_content = "Gracias a tu suero, me siento mucho mejor.",
  ui_story_5068_50680902_3_dialog_content = "Esta niebla negra... Parece mucho más potente que lo que Lady Sheol me dio antes.",
  ui_story_5068_50680902_4_dialog_content = "...",
  ui_story_5068_50680902_5_dialog_content = "Esto no es bueno, Isa!",
  ui_story_5068_50680902_6_dialog_content = "¿Qué pasó ahora?",
  ui_story_5068_50680902_7_dialog_content = "Mira afuera... ¡Un montón de habitantes de la barriada están empezando a rodear este lugar!",
  ui_story_5068_50680902_8_dialog_content = "¿Habitantes de barrios marginales? Pero, ¿qué hacen aquí?",
  ui_story_5068_50680902_9_dialog_content = "¡Oh no...!",
  ui_story_5068_50680902_10_dialog_content = "¡Espera! ¡No tienes permitido entrar!",
  ui_story_5068_50680902_11_dialog_content = "¿Quiénes... Quiénes son ustedes? ¿Dónde está el médico? *tos, tos* Necesitamos su ayuda... De repente apareció toda esta niebla negra, y todos...",
  ui_story_5068_50680902_12_dialog_content = "Urgh... Me duele mucho... ¿Dónde está el médico...?",
  ui_story_5068_50680902_13_dialog_content = "Hay tanta gente, y algunos de ellos ya se han desmayado...",
  ui_story_5068_50680902_14_dialog_content = "Eleanor! ¡A todos! Yo... ¡Necesito su ayuda!",
  ui_story_5068_50680902_15_dialog_content = "¡Sí, señorita Rebecca!",
  ui_story_5068_50680902_16_dialog_content = "¿Ah?",
  ui_story_5068_50680902_17_dialog_content = "¡Deja de quejarte! La escuchaste, ¡ahora ve a echar una mano!",
  ui_story_5068_50680902_18_dialog_content = "Por favor, ¡no entren en pánico, todos! Mantengan su distancia entre sí y eviten pisotear a los inconscientes.",
  ui_story_5068_50680902_19_dialog_content = "... Todos vinieron buscando ayuda. ¡Me niego a abandonar a ninguno de ellos!",
  ui_story_5068_50680902_20_dialog_content = "Rebecca? ¿Qué estás...",
  ui_story_5068_50680902_21_dialog_content = "No hay tiempo, así que tendré que atenderlos a todos de una vez...",
  ui_story_5068_50680902_22_dialog_content = "Espera, ¿vas a tratar a tantas personas al mismo tiempo? ¿Puede tu cuerpo soportar eso?!",
  ui_story_5068_50680902_23_dialog_content = "¡Jaaaa—!!",
  ui_story_5068_50680902_24_dialog_content = "*Tose* Se está volviendo... más fácil respirar...",
  ui_story_5068_50680902_25_dialog_content = "La doctora... nos salvó de nuevo...",
  ui_story_5068_50680902_26_dialog_content = "...",
  ui_story_5068_50680902_27_dialog_content = "¡¡Señorita Rebecca!!!",
  ui_story_5068_50680902_28_dialog_content = "¡Oye! ¡Deja de asustarme así! Rebecca?!",
  ui_story_5068_50680902_29_dialog_content = "¿Están... están todos bien ahora? Estoy un poco... sin aliento. Eleanor, ve a revisar cómo están por mí...",
  ui_story_5068_50680902_30_dialog_content = "Rebecca, yo—",
  ui_story_5068_50680902_31_dialog_content = "¡Ve!",
  ui_story_5068_50680902_32_dialog_content = "...",
  ui_story_5068_50680902_33_dialog_content = "¡Oye! ¿Rebecca? ¡¿Rebecca?!",
  ui_story_5068_50680902_34_dialog_content = "¡Deja de sacudirla! Gastó demasiada Lumina, así que está muy delicada en este momento. ¡Necesitamos encontrar un lugar seguro para que se recupere!",
  ui_story_5068_50680902_35_dialog_content = "Yo... estoy bien. Eleanor, ¿los demás—",
  ui_story_5068_50680902_36_dialog_content = "Están bien por ahora, señorita Rebecca. Gracias a su tratamiento, todo lo que necesitan es descansar para recuperarse por completo.",
  ui_story_5068_50680902_37_dialog_content = "... ¿En serio? Qué alivio.",
  ui_story_5068_50680902_38_dialog_content = "¿Los Lobos Negros han perdido completamente la cabeza?! ¡¿Cómo podrían hacer algo tan horrible?!",
  ui_story_5068_50680902_39_dialog_content = "Pueden tener otro objetivo en mente.",
  ui_story_5068_50680902_40_dialog_content = "... ¡Están intentando obligar a la señorita Rebecca a salir de su escondite!",
  ui_story_5068_50680902_41_dialog_content = "¡Argh... Este lugar está completamente comprometido ahora!",
  ui_story_5068_50680902_42_dialog_content = "Entonces, vayamos al Gremio de Explorador Nublar. No se me ocurre un lugar más seguro para ir en este momento.",
  ui_story_5068_50680902_43_dialog_content = "¡Entendido! ¡Llevaré Rebecca!",
  ui_story_5068_50680902_44_dialog_content = "No, déjame eso a mí.",
  ui_story_5068_50680902_45_dialog_content = "Tú... ¡bien! Pero ten cuidado!",
  ui_story_5068_50680902_46_dialog_content = "...",
  ui_story_5068_50680902_47_dialog_content = "En cuanto a ustedes, quédense aquí y mantengan todo bajo control. ¡Una vez que estas personas se hayan recuperado, envíenlas a casa de inmediato!",
  ui_story_5068_50680902_48_dialog_content = "¡Sí!",
  ui_story_5068_50681001_1_dialog_content = "Director...",
  ui_story_5068_50681001_2_dialog_content = "Hemos confirmado la presencia de Rebecca en el área donde desapareció el Equipo B, pero...",
  ui_story_5068_50681001_3_dialog_content = "Te enseñé mejor que andarte con rodeos, ahora dilo.",
  ui_story_5068_50681001_4_dialog_content = "Es solo que sus ataques de veneno dificultan que nos acerquemos a ella... Mucho menos capturarla viva.",
  ui_story_5068_50681001_5_dialog_content = "... Realmente tiene un don si aprendió a controlar su veneno en solo un año.",
  ui_story_5068_50681001_6_dialog_content = "Pero aún eres mucho más fuerte que ella, Director. Después de todo, creaste una niebla negra que <color=#FFB400>contrarresta específicamente su veneno</color>!",
  ui_story_5068_50681001_7_dialog_content = "Eso no es de tu incumbencia.",
  ui_story_5068_50681001_8_dialog_content = "P-Perdóname, Director! Solo mantendré mi boca cerrada...",
  ui_story_5068_50681001_9_dialog_content = "Entonces, ¿dónde está Rebecca ahora mismo?",
  ui_story_5068_50681001_10_dialog_content = "La encontramos en su Clínica Subterránea, pero tenía algunos aliados a su lado. La están llevando al Gremio Cloudrover en este momento.",
  ui_story_5068_50681001_11_dialog_content = "Pero lo cierto es que aún no es el momento adecuado para enfrentarlos.",
  ui_story_5068_50681001_12_dialog_content = "¿El Gremio de Explorador Nublar?",
  ui_story_5068_50681001_13_dialog_content = "Eso sí complica las cosas, pero aún tenemos otras opciones.",
  ui_story_5068_50681001_14_dialog_content = "Está bien, deberíamos estar a salvo ahora que llegamos al Gremio Cloudrover.",
  ui_story_5068_50681001_15_dialog_content = "¿Te sientes mejor ahora, Rebecca?",
  ui_story_5068_50681001_16_dialog_content = "Sí... Perdón por molestar a todos hace un momento.",
  ui_story_5068_50681001_17_dialog_content = "¡No necesitas ser tan educado conmigo! El gremio Cloudrover está en nuestro territorio, así que solo túmbate y relájate mientras nos encargamos del resto.",
  ui_story_5068_50681001_18_dialog_content = "Parece que a esta habitación todavía le faltan algunos suministros, ¡pero no te preocupes! ¡Iré a comprar algunos para ti!",
  ui_story_5068_50681001_19_dialog_content = "Espera, Isa... Es demasiado peligroso salir ahora mismo, ¿no?",
  ui_story_5068_50681001_20_dialog_content = "Como dije, este es el Gremio Cloudrover, así que los Lobos Negros tendrían que ser realmente estúpidos para enfrentarse a nosotros aquí. No te preocupes, ¡volveré antes de que te des cuenta!",
  ui_story_5068_50681001_21_dialog_content = "PlayerName... No te ves muy bien... ¿Te sientes bien?",
  ui_story_5068_50681001_22_dialog_content = "Estoy bien. Solo que este trabajo resultó ser mucho más complicado de lo que pensaba...",
  ui_story_5068_50681001_23_dialog_content = "Pero no te preocupes, solo necesito algo de tiempo para pensar. Adelante, descansa un poco.",
  ui_story_5068_50681001_24_dialog_content = "Lo siento por... causarte tantos problemas...",
  ui_story_5068_50681001_25_dialog_content = "Mmm...",
  ui_story_5068_50681001_26_dialog_content = "...!!!",
  ui_story_5068_50681001_27_dialog_content = "Eleanor... Apúrate...",
  ui_story_5068_50681001_28_dialog_content = "PlayerName, puedes irte ahora.",
  ui_story_5068_50681001_29_dialog_content = "¿Eh? P-Pero Rebecca está...",
  ui_story_5068_50681001_30_dialog_content = "¡Dije que te fueras! Rebecca necesita descansar ahora mismo!",
  ui_story_5068_50681001_31_dialog_content = "Vaya, casi me olvido de preguntar. Oye, Rebecca, ¿qué exactamente necesitas que yo haga?",
  ui_story_5068_50681001_32_dialog_content = "Err...",
  ui_story_5068_50681001_33_dialog_content = "R-Rebecca...? ¿Q-Qué está pasando aquí?!",
  ui_story_5068_50681001_34_dialog_content = "Isa... Por favor... No mires...",
  ui_story_5068_50681001_35_dialog_content = "Err...",
  ui_story_5068_50681001_36_dialog_content = "¿Es esto... el veneno?!",
  ui_story_5068_50681001_37_dialog_content = "Pero... ¿por qué hay veneno saliendo de tu piel? ¡Está... Está empezando a ponerse rojo brillante! ¡Necesitamos limpiarlo de tu piel de inmediato!",
  ui_story_5068_50681001_38_dialog_content = "¡No la toques!",
  ui_story_5068_50681001_39_dialog_content = "¡No la toques?! ¡Mi hermana está sufriendo, ahora suéltame! ¿Cómo puedes quedarte ahí parado y mirar?!",
  ui_story_5068_50681001_40_dialog_content = "¡Tampoco quiero ver a Rebecca sufrir! Pero ahora mismo...",
  ui_story_5068_50681001_41_dialog_content = "No hay nada que podamos hacer para ayudarla.",
  ui_story_5068_50681001_42_dialog_content = "Rebecca produjo demasiado suero antes. La única forma de que se estabilice es expulsando tanto veneno.",
  ui_story_5068_50681001_43_dialog_content = "Si se rompe el equilibrio entre los dos... Es probable que ella pierda la cordura.",
  ui_story_5068_50681001_44_dialog_content = "Además, este veneno es extremadamente peligroso para la mayoría de las personas. ¡Estoy seguro de que ella no quiere que nadie entre en contacto con él!",
  ui_story_5068_50681001_45_dialog_content = "Oh...",
  ui_story_5068_50681001_46_dialog_content = "Rebecca...",
  ui_story_5068_50681001_47_dialog_content = "¡Pero ella nunca tuvo que hacer esto antes! Soy su hermana mayor, ¿cómo es que nunca supe de esto?!",
  ui_story_5068_50681001_48_dialog_content = "Es algo que ella decidió asumir por sí misma. También tiene sus razones para hacer esto.",
  ui_story_5068_50681001_49_dialog_content = "¡No me importan sus razones! ¡No puedes dejar que Rebecca se lastime así!",
  ui_story_5068_50681001_50_dialog_content = "V-Verónica...",
  ui_story_5068_50681001_51_dialog_content = "Yo... Yo elegí esto para mí mismo, Isa. Es mi carga que soportar... Así que no culpes a nadie más.",
  ui_story_5068_50681001_52_dialog_content = "No quería... que te preocuparas demasiado. Pero aún así... lo descubriste.",
  ui_story_5068_50681001_53_dialog_content = "Rebecca! ¿Te... Te sientes mejor?",
  ui_story_5068_50681001_54_dialog_content = "Sí... Una vez que saque todo esto de mi sistema... me siento mucho mejor.",
  ui_story_5068_50681001_55_dialog_content = "¿Es esto lo que guardabas en todos esos frascos en tu habitación oculta? Si es así, eso significa que has pasado por esto muchas veces...",
  ui_story_5068_50681001_56_dialog_content = "¿Qué frascos? ¿¡Y habitación escondida?! Si no quieres que me preocupe, ¡entonces dime todo!",
  ui_story_5068_50681001_57_dialog_content = "Realmente... no es un problema tan grande. Es solo que... Desde <color=#FFB400>aquel día</color>, decidí investigar sobre mi veneno.",
  ui_story_5068_50681001_58_dialog_content = "Tal vez sea porque comencé demasiado tarde o tal vez tenía demasiada prisa, pero... Mi investigación resultó en estos efectos secundarios.",
  ui_story_5068_50681001_59_dialog_content = "Pero no voy a detenerme.",
  ui_story_5068_50681001_60_dialog_content = "En aquel entonces... no podía usar mi \"don\" para ayudar a nadie. Todo lo que podía hacer era correr y esconderme como un cobarde...",
  ui_story_5068_50681001_61_dialog_content = "No fue tu culpa, Rebecca! Los Lobos Negros tienen la culpa, ¡no tú!",
  ui_story_5068_50681001_62_dialog_content = "Pero... Pero si hubiera aprendido a controlar mi veneno antes, podría haber evitado que entraran en nuestra casa...",
  ui_story_5068_50681001_63_dialog_content = "Incluso ahora, todavía tengo personas que quiero proteger.",
  ui_story_5068_50681001_64_dialog_content = "Y si protegerlos significa soportar un poco más de dolor... Entonces es un precio que estoy dispuesto a pagar.",
  ui_story_5068_50681001_65_dialog_content = "Eso no parecía un poco más de dolor hace un momento. Estabas claramente sufriendo... ¡Argh, qué clase de hermana inútil soy?!",
  ui_story_5068_50681001_66_dialog_content = "No deberías tener que hacer esto... ¡Es cierto! ¡Ya no tendrás que hacer esto más!",
  ui_story_5068_50681001_67_dialog_content = "Simplemente le pediré a Lady Sheol que te ofrezca un trabajo en el gremio. ¡Cuando regrese de su reunión de negocios, hablaré bien de ti!",
  ui_story_5068_50681001_68_dialog_content = "¡De esa manera puedes vivir y trabajar con total seguridad! ¡Nunca más tendrás que temer por tu vida ni lastimarte con más investigaciones!",
  ui_story_5068_50681001_69_dialog_content = "En cuanto a los detalles, ¡déjame el resto a mí!",
  ui_story_5068_50681001_70_dialog_content = "Isa... A pesar de todo este tiempo, todavía me ves como un niño.",
  ui_story_5068_50681001_71_dialog_content = "¡Eso es lo que hacen las hermanas mayores! No te preocupes, ¡sé exactamente qué hacer!",
  ui_story_5068_50681001_72_dialog_content = "Iré a comprarte un bonito par de pijamas mientras descansas mucho. ¡Nos vemos en un rato!",
  ui_story_5068_50681001_73_dialog_content = "...",
  ui_story_5068_50681001_74_dialog_content = "¿Aún te preocupa algo, Señorita Rebecca?",
  ui_story_5068_50681001_75_dialog_content = "No puedo dejar de preocuparme por esos pacientes de antes. Salimos con tanta prisa que no pude evaluar a ninguno de ellos más de cerca.",
  ui_story_5068_50681001_76_dialog_content = "Ya no estamos en la clínica, así que si les pasa algo a ellos...",
  ui_story_5068_50681001_77_dialog_content = "No te preocupes, volveré y revisaré cómo están. Dejamos algunos suministros médicos atrás, así que también puedo distribuir esos.",
  ui_story_5068_50681001_78_dialog_content = "¿Te vas justo ahora? Pero, ¿y si los Lobos Negros todavía están merodeando por la clínica?",
  ui_story_5068_50681001_79_dialog_content = "No me estás subestimando, ¿verdad, PlayerName?",
  ui_story_5068_50681001_80_dialog_content = "De todos modos, aún no me siento cómodo dejándote sola en el Gremio Cloudrover, señorita Rebecca.",
  ui_story_5068_50681001_81_dialog_content = "Este lugar parece lo suficientemente seguro. Además, PlayerName todavía está aquí y mi hermana debería regresar pronto.",
  ui_story_5068_50681001_82_dialog_content = "Me siento mucho mejor ahora, pero no se puede decir lo mismo de nuestros pacientes. Nos necesitan en este momento.",
  ui_story_5068_50681001_83_dialog_content = "Entendido. No tardaré mucho, pero por favor cuídate bien mientras estoy fuera.",
  ui_story_5068_50681001_84_dialog_content = "Rebecca parece confiar en ti, PlayerName, así que haré lo mismo.",
  ui_story_5068_50681001_85_dialog_content = "Está bien...",
  ui_story_5068_50681001_86_dialog_content = "Lo siento, PlayerName... No te asusté hace un momento, ¿verdad?",
  ui_story_5068_50681001_87_dialog_content = "Para nada. Por favor, no te sientas así.",
  ui_story_5068_50681001_88_dialog_content = "Es solo que... ¿podrías prometerme algo?",
  ui_story_5068_50681001_89_dialog_content = "¿Qué es?",
  ui_story_5068_50681001_90_dialog_content = "Pase lo que pase, por favor no te lastimes nunca más.",
  ui_story_5068_50681001_91_dialog_content = "PlayerName...",
  ui_story_5068_50681001_92_dialog_content = "Veamos... Definitivamente necesita cosas para bañarse, así como una toalla... ¡Ah, simplemente le compraré un montón de toallas!",
  ui_story_5068_50681001_93_dialog_content = "¡Guau, apuesto a que Rebecca se vería súper lindo en esto! Ahora solo necesito...",
  ui_story_5068_50681001_94_dialog_content = "¡¿?!",
  ui_story_5068_50681001_95_dialog_content = "*tose, tose* ¿Quién está ahí? ¿Y cómo te atreves a causar problemas... en el territorio del Gremio Cloudrover?!",
  ui_story_5068_50681001_96_dialog_content = "<color=#e8d9bb>Maricón-</color>",
  ui_story_5068_50681001_97_dialog_content = "Eh...?!",
  ui_story_5068_50681001_98_dialog_content = "Los lobos negros...",
  ui_story_5068_50681101_1_dialog_content = "Espera... ¿Dónde estoy?",
  ui_story_5068_50681101_2_dialog_content = "¿Y estoy todo atado?! Tsk, esos Lobos Negros siempre recurren a trucos tan bajos.",
  ui_story_5068_50681101_3_dialog_content = "Aun así, la forma en que me ataron... Je, tus antepasados deben estar muy avergonzados.",
  ui_story_5068_50681101_4_dialog_content = "...",
  ui_story_5068_50681101_5_dialog_content = "¿Qué pasa ahora? ¿No puedes hablar con una chica incluso después de secuestrarla?!",
  ui_story_5068_50681101_6_dialog_content = "¡Dile a quien esté a cargo que salga aquí! ¡Tengo una cuenta que saldar con ellos!",
  ui_story_5068_50681101_7_dialog_content = "Isa Svanedona, la hija mayor de la familia Svanedona que casualmente estaba estudiando en el extranjero en ese momento.",
  ui_story_5068_50681101_8_dialog_content = "Me pregunto qué tipo de neblina negra producirá tu cuerpo al quemarse... ¿Causará un dolor insoportable a las personas? ¿O tal vez les dará convulsiones incontrolables?",
  ui_story_5068_50681101_9_dialog_content = "Jejeje. Qué lástima que no heredaste los dones de tu familia.",
  ui_story_5068_50681101_10_dialog_content = "¡Cierra la boca! Mi familia puede que se haya ido, pero yo sigo aquí, ¡y me vengaré tarde o temprano!",
  ui_story_5068_50681101_11_dialog_content = "¿En serio? Porque no parece que seas bueno en algo más que hablar mucho. Por otro lado, tu hermana...",
  ui_story_5068_50681101_12_dialog_content = "¿Qué quieres con ella?! ¡No dejaré que los Lobos Negros lastimen más a mi familia!",
  ui_story_5068_50681101_13_dialog_content = "¿Qué quiero? Je... Todo lo que quiero es terminar lo que comencé.",
  ui_story_5068_50681101_14_dialog_content = "Te advierto, aléjate de mi hermana... O si no...",
  ui_story_5068_50681101_15_dialog_content = "¿O qué? Espera, déjame adivinar... ¿Vas a liberarte de tus ataduras y matarme donde estoy parado?",
  ui_story_5068_50681101_16_dialog_content = "¡Urgh...! ¡Cállate!",
  ui_story_5068_50681102_1_dialog_content = "S-Si quieres llegar a mi hermana... Tendrás que matarme primero...",
  ui_story_5068_50681102_2_dialog_content = "¿Matar a ti? Por favor, no soy tan estúpido como para enfrentarme directamente al gremio Cloudrover.",
  ui_story_5068_50681102_3_dialog_content = "Tal vez no seas lo suficientemente tonto... Pero aún eres bastante tonto... Jajaja...",
  ui_story_5068_50681102_4_dialog_content = "¡Eso es suficiente de ti!",
  ui_story_5068_50681102_5_dialog_content = "Cuando te enfrentas a un poder abrumador, lo único que puedes hacer es rendirte y morir... Después de todos mis años de lucha, esa es la única verdad que he aprendido.",
  ui_story_5068_50681102_6_dialog_content = "Y ahora, estoy a punto de enseñarte la misma lección... Deberías sentirte agradecido.",
  ui_story_5068_50681102_7_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5068_50681102_8_dialog_content = "¿Eres tú, Isa?",
  ui_story_5068_50681102_9_dialog_content = "No... Qué raro, no hay nadie en la puerta.",
  ui_story_5068_50681102_10_dialog_content = "¿Eh? Hay una carta en el suelo... ¡Y dice \"Para Rebecca\"!",
  ui_story_5068_50681102_11_dialog_content = "¿Para mí? Déjame ver...",
  ui_story_5068_50681102_12_dialog_content = "No... ¡Esto no puede ser!",
  ui_story_5068_50681102_13_dialog_content = "Es Isa... ¡Ha sido capturada por los Lobos Negros! Pero ella dijo que no le harían nada en el territorio del Gremio Cloudrover!",
  ui_story_5068_50681102_14_dialog_content = "Si los Lobos Negros están dispuestos a ignorar las reglas de Umbraton... Significa que están listos para luchar abiertamente ahora.",
  ui_story_5068_50681102_15_dialog_content = "Eleanor todavía no ha vuelto... ¿podría haberle pasado algo también?",
  ui_story_5068_50681102_16_dialog_content = "Nos preocuparemos por eso más tarde. ¿Qué más dice la carta?",
  ui_story_5068_50681102_17_dialog_content = "Dice que si queremos que ella permanezca ilesa, debo presentarme en su escondite en la próxima hora... También hay una dirección escrita aquí.",
  ui_story_5068_50681102_18_dialog_content = "Entonces te perseguían a ti todo el tiempo. ¡Estarías cayendo justo en sus manos si fueras allá ahora mismo!",
  ui_story_5068_50681102_19_dialog_content = "Pero secuestraron a Isa... ¡No tengo opción!",
  ui_story_5068_50681102_20_dialog_content = "¿Cómo podría abandonarla cuando nos acabamos de encontrar después de tanto tiempo? No solo eso, podría haber más miembros de mi familia allí...",
  ui_story_5068_50681102_21_dialog_content = "Pero prometí encontrar una manera de ayudarte...",
  ui_story_5068_50681102_22_dialog_content = "Ya no hay tiempo... Durante el último año, no he hecho más que correr y esconderme en mi clínica subterránea.",
  ui_story_5068_50681102_23_dialog_content = "No tenía forma de saber si alguien de mi familia había sobrevivido, o si habían sido capturados y torturados... Mi cobardía es lo que causó todo esto.",
  ui_story_5068_50681102_24_dialog_content = "A pesar de eso, todavía sigo huyendo. Yo... incluso te pedí que pensaras en una respuesta para mí.",
  ui_story_5068_50681102_25_dialog_content = "El objetivo de investigar mi veneno era encontrar una forma de proteger a los que me importan, pero no solo fracasé, sino que también puse en riesgo la vida de mi hermana...",
  ui_story_5068_50681102_26_dialog_content = "No puedo seguir huyendo. Ya no más.",
  ui_story_5068_50681102_27_dialog_content = "Si secuestraran a tus seres queridos, no te detendrías ante nada para rescatarlos, ¿verdad?",
  ui_story_5068_50681102_28_dialog_content = "... Sabía que no podría convencerte de lo contrario, pero esto es demasiado peligroso para solo nosotros dos.",
  ui_story_5068_50681102_29_dialog_content = "El Gremio de Explorador Nublar... Umbraton... Incluso las pandillas...",
  ui_story_5068_50681102_30_dialog_content = "Espera, conozco un grupo de mercenarios aquí en la ciudad. ¡Quizás puedan ayudarnos!",
  ui_story_5068_50681201_1_dialog_content = "Nunca imaginé que aceptarías un trabajo que implicara rescatar a un rehén, PlayerName.",
  ui_story_5068_50681201_2_dialog_content = "Es una larga historia... Pero tenemos que sacar a Isa de allí a salvo.",
  ui_story_5068_50681201_3_dialog_content = "Gracias por aparecer con tan poco tiempo de aviso, por cierto. ¡Esto debería ayudarnos mucho!",
  ui_story_5068_50681201_4_dialog_content = "¡No te preocupes! El Capitán Luke no pudo venir personalmente, ¡pero daremos todo lo que tenemos!",
  ui_story_5068_50681201_5_dialog_content = "Estamos en el escondite de los Lobos Negros, ¡así que mantente alerta! La niebla negra es especialmente densa aquí, lo que significa que probablemente la estén produciendo en algún lugar de este lugar.",
  ui_story_5068_50681201_6_dialog_content = "...",
  ui_story_5068_50681201_7_dialog_content = "<color=#e8d9bb>Criiiiik...</color>",
  ui_story_5068_50681201_8_dialog_content = "¿De verdad crees que Isa está aquí? Todo lo que veo son un montón de frascos y contenedores.",
  ui_story_5068_50681201_9_dialog_content = "Puedo sentir la presencia de Isa cerca, pero estos frascos...",
  ui_story_5068_50681201_10_dialog_content = "Hay nombres escritos en ellos...",
  ui_story_5068_50681201_11_dialog_content = "Tío Albert, Jessica... Mamá y Papá... Aaron...",
  ui_story_5068_50681201_12_dialog_content = "Sus nombres están en estos frascos de veneno, lo que significa que todos ellos están...",
  ui_story_5068_50681201_13_dialog_content = "Rebecca...",
  ui_story_5068_50681201_14_dialog_content = "Todos estos nombres...",
  ui_story_5068_50681201_15_dialog_content = "Incluso... Incluso hay un gran frasco vacío con mi nombre en él.",
  ui_story_5068_50681201_16_dialog_content = "... P-Pero no veo uno con el nombre de Isa! ¡Eso significa que no llegamos demasiado tarde!",
  ui_story_5068_50681201_17_dialog_content = "No, PlayerName. Verás... Isa nunca heredó la habilidad de nuestra familia.",
  ui_story_5068_50681201_18_dialog_content = "Lo que significa que tal vez ya esté...",
  ui_story_5068_50681201_19_dialog_content = "No saques conclusiones precipitadas todavía. ¡Primero tenemos que encontrarla!",
  ui_story_5068_50681201_20_dialog_content = "¡Cuidado! ¡El enemigo se acerca!",
  ui_story_5068_50681201_21_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc. </color>",
  ui_story_5068_50681201_22_dialog_content = "En nombre de los Lobos Negros, bienvenido a nuestra base de operaciones.",
  ui_story_5068_50681201_23_dialog_content = "... Es Arte, ¡el Director de los Lobos Negros!",
  ui_story_5068_50681201_24_dialog_content = "Jejeje... Ha pasado un tiempo desde que este lugar ha tenido acción.",
  ui_story_5068_50681201_25_dialog_content = "Es grosero traer una multitud a la fiesta cuando solo te invité a ti... Rebecca Svanedona.",
  ui_story_5068_50681201_26_dialog_content = "Qué lástima. Si hubieras llegado un poco antes, quizás habrías tenido la oportunidad de verlo una última vez... ¿Tu padre, verdad? El hombre tenía una determinación increíble; de todos mis sujetos de prueba, él duró más tiempo.",
  ui_story_5068_50681201_27_dialog_content = "¡Por qué tú...!",
  ui_story_5068_50681201_28_dialog_content = "Al principio solo quería desahogar mi odio hacia la Familia Svanedona, pero cuando descubrí tu secreto... supe que había sido elegido para algo más grande.",
  ui_story_5068_50681201_29_dialog_content = "Tampoco deberías estar tan molesto conmigo. Después de todo, si no los hubiera encarcelado, no habrían vivido para ver otro año. ¿No estás de acuerdo?",
  ui_story_5068_50681201_30_dialog_content = "Además, si alguien tiene la culpa... Son ellos por no producir su veneno hasta después de morir. No puedo hacer mi niebla negra sin él.",
  ui_story_5068_50681201_31_dialog_content = "Pero tú eres diferente, Rebecca. Me aseguraré de apreciarte durante el mayor tiempo posible—",
  ui_story_5068_50681201_32_dialog_content = "¡No dejaré que le hagas nada nunca más!",
  ui_story_5068_50681201_33_dialog_content = "¿Vaya? Creo que te reconozco. Eres... el Celestita, ¿no es cierto?",
  ui_story_5068_50681201_34_dialog_content = "Tch... Si tan solo nos hubiéramos conocido en otras circunstancias.",
  ui_story_5068_50681201_35_dialog_content = "He oído hablar de tus poderes antes... ¿Tal vez tengamos la oportunidad de trabajar juntos en el futuro?",
  ui_story_5068_50681201_36_dialog_content = "¡Nunca trabajaría con un desalmado idiota como tú! ¿Ahora dónde está Isa?!",
  ui_story_5068_50681201_37_dialog_content = "La disputa entre los Lobos Negros y la Familia Svanedona no debería preocupar a un Celestita, así que, ¿podrías por favor calmarte por ahora?",
  ui_story_5068_50681201_38_dialog_content = "¡En tus sueños! Estoy aquí para ayudar a mi amiga a rescatar a su familia.",
  ui_story_5068_50681201_39_dialog_content = "Y aquí estaba yo intentando ser un buen anfitrión. Qué ridículo.",
  ui_story_5068_50681201_40_dialog_content = "¡Sácala!",
  ui_story_5068_50681201_41_dialog_content = "...",
  ui_story_5068_50681201_42_dialog_content = "Isa!!",
  ui_story_5068_50681201_43_dialog_content = "Urgh... ¿Rebecca? ¡¿Qué estás haciendo aquí?!",
  ui_story_5068_50681201_44_dialog_content = "¡No deberías haber venido aquí! ¿¡Cómo pudiste caer en una trampa tan obvia?! No te preocupes por mí, solo corre antes de que sea demasiado tarde!",
  ui_story_5068_50681201_45_dialog_content = "¡Suéltame a mi hermana!",
  ui_story_5068_50681201_46_dialog_content = "Claro, estaría más que feliz de dejarla ir. Pero—",
  ui_story_5068_50681201_47_dialog_content = "Tienes que quedarte en su lugar.",
  ui_story_5068_50681201_48_dialog_content = "¿Qué quieres?",
  ui_story_5068_50681201_49_dialog_content = "¿No fui lo suficientemente claro? Rebecca debe quedarse con los Lobos Negros.",
  ui_story_5068_50681201_50_dialog_content = "No le haré daño ni a un solo cabello; después de todo, ella es la única que puede ayudarme a avanzar en mi investigación sobre la niebla negra. Incluso estoy dispuesto a dejar el pasado atrás.",
  ui_story_5068_50681201_51_dialog_content = "También puedo presentarte a <color=#FFB400>la mujer</color> que me la recomendó en primer lugar.",
  ui_story_5068_50681201_52_dialog_content = "Pero si ella se sale de línea aunque sea una vez... Jejeje, eres bienvenido a intentarlo, Rebecca.",
  ui_story_5068_50681201_53_dialog_content = "Solo ten en cuenta que cooperar no solo es lo mejor para ti. También es la única opción que te queda.",
  ui_story_5068_50681201_54_dialog_content = "¿Estás bromeando? Hablando de tiempos pasados y de alguna mujer... ¡Rebecca es claramente la víctima aquí!",
  ui_story_5068_50681201_55_dialog_content = "¿Oh? Está bien si la Caelestite no sabe nada, pero tú Rebecca? ¿No me digas que has estado ocultando los secretos de tu familia solo para aprovechar su confianza?",
  ui_story_5068_50681201_56_dialog_content = "No tengo idea de lo que estás hablando.",
  ui_story_5068_50681201_57_dialog_content = "Si ese es el caso, entonces tu hermana no te contó lo que sucedió entre los Lobos Negros y la Familia Svanedona.",
  ui_story_5068_50681201_58_dialog_content = "En aquel entonces, todo lo que quería era invitarte a trabajar conmigo, pero la Familia Svanedona nos despreciaba a nosotros, los Lobos Negros. No solo nos rechazaron, sino que también hirieron a muchos de nuestros miembros.",
  ui_story_5068_50681201_59_dialog_content = "¡Mentiroso! ¡Los Lobos Negros fueron los primeros en salirse de tono! ¡La pelea solo comenzó porque ustedes matones hicieron el primer movimiento!",
  ui_story_5068_50681201_60_dialog_content = "Cállala.",
  ui_story_5068_50681201_61_dialog_content = "¡Sí!",
  ui_story_5068_50681201_62_dialog_content = "Mmm, mmm, mmm—",
  ui_story_5068_50681201_63_dialog_content = "¿Me invitas a trabajar contigo?",
  ui_story_5068_50681201_64_dialog_content = "¿Oh? Parece que tenía razón, no tienes idea de lo que realmente sucedió.",
  ui_story_5068_50681201_65_dialog_content = "Después de todo este tiempo, ¿ni siquiera tu amigo más cercano tuvo el valor de decírtelo?",
  ui_story_5068_50681201_66_dialog_content = "Ella sabe muy bien lo que pasó en aquel entonces. Después de todo, solía ser una Loba Negra ella misma.",
  ui_story_5068_50681201_67_dialog_content = "¡...!",
  ui_story_5068_50681201_68_dialog_content = "No te refieres a... Eleanor?",
  ui_story_5068_50681301_1_dialog_content = "¿No te refieres a... Eleanor?",
  ui_story_5068_50681301_2_dialog_content = "Jejeje. ¿Sorprendido?",
  ui_story_5068_50681301_3_dialog_content = "Eleanor resulta ser uno de los miembros más antiguos en la historia de los Lobos Negros.",
  ui_story_5068_50681301_4_dialog_content = "La envié a infiltrarse en la Familia Svanedona hace mucho tiempo... para recopilar cada pedacito de información sobre ellos.",
  ui_story_5068_50681301_5_dialog_content = "Incluso podrías decir que la desaparición de toda la familia fue gracias a ella.",
  ui_story_5068_50681301_6_dialog_content = "Eleanor... N-No... ¡Eso es imposible!",
  ui_story_5068_50681301_7_dialog_content = "El día que nuestra familia fue atacada... ¡Eleanor arriesgó su vida para salvarme!",
  ui_story_5068_50681301_8_dialog_content = "¡Ha estado a mi lado desde entonces, sin importar lo que nos haya pasado!",
  ui_story_5068_50681301_9_dialog_content = "Eleanor ¡no podría ser uno de ustedes!",
  ui_story_5068_50681301_10_dialog_content = "Solo estoy exponiendo los hechos, nada más. Traicionar a otros es un hábito difícil de romper, Rebecca; sería inteligente que lo recordaras.",
  ui_story_5068_50681301_11_dialog_content = "Me sorprende que el héroe de los Lobos Negros no esté aquí contigo hoy. No es que me importe mucho, ya que tú eres el único que me interesa, Rebecca Svanedona.",
  ui_story_5068_50681301_12_dialog_content = "...",
  ui_story_5068_50681301_13_dialog_content = "(Si Eleanor no ha sido capturada, eso significa que probablemente esté de vuelta en la clínica en este momento...)",
  ui_story_5068_50681301_14_dialog_content = "(Esa mirada en los ojos de Rebecca... ¿Qué podría estar pensando?)",
  ui_story_5068_50681301_15_dialog_content = "Pero basta de todo eso. ¿Ya tienes una respuesta para mí, Rebecca?",
  ui_story_5068_50681301_16_dialog_content = "¡No—!!!",
  ui_story_5068_50681301_17_dialog_content = "Mmm, mmm, mmm...",
  ui_story_5068_50681301_18_dialog_content = "Isa!!!",
  ui_story_5068_50681301_19_dialog_content = "Esa espada colgando sobre su cabeza no es solo por apariencia, ¿sabes?",
  ui_story_5068_50681301_20_dialog_content = "Al final del día, lo único que busco es ese poder tuyo.",
  ui_story_5068_50681301_21_dialog_content = "Si simplemente te hubieras unido a nosotros en lugar de esconderte como un cobarde durante el último año, la gente en esos frascos no habría muerto de manera tan vergonzosa.",
  ui_story_5068_50681301_22_dialog_content = "Pero ahora te estoy dando una última oportunidad. Si no quieres que tu hermana termine como los demás, ¡admite que todo fue culpa tuya! ¡Admite que eres la hija del desastre!",
  ui_story_5068_50681301_23_dialog_content = "La hija del desastre...",
  ui_story_5068_50681301_24_dialog_content = "...¿Es realmente toda mi culpa? La desaparición de mi familia... El veneno dañino que nunca deja de fluir de mí...",
  ui_story_5068_50681301_25_dialog_content = "Desde que nací, nunca pude alcanzar y tocar cosas bonitas como una persona normal...",
  ui_story_5068_50681301_26_dialog_content = "No la escuches, Rebecca! ¡Mira lo que hizo con toda tu familia! ¡No tienes ninguna razón para rendirte ante ella!",
  ui_story_5068_50681301_27_dialog_content = "Tal vez, pero ¿qué otra opción tiene ella?",
  ui_story_5068_50681301_28_dialog_content = "El veneno en su cuerpo será su fin algún día. En lugar de desperdiciarlo, ¿por qué no dejarme hacer algo útil con él?",
  ui_story_5068_50681301_29_dialog_content = "...",
  ui_story_5068_50681301_30_dialog_content = "(Si esto continúa, Rebecca podría realmente tomar esa decisión...)",
  ui_story_5068_50681301_31_dialog_content = "(Como Caelestite, ¡debe haber algo que pueda hacer!)",
  ui_story_5068_50681301_32_option_content = "¡Potencia de fuerza!",
  ui_story_5068_50681301_33_dialog_content = "(¡Rebecca! ¡Rebecca!)",
  ui_story_5068_50681301_34_dialog_content = "(... PlayerName? ¿Es esto... también uno de tus poderes?)",
  ui_story_5068_50681301_35_dialog_content = "(¡Por favor, solo escúchame! ¡No hay tiempo para explicar!)",
  ui_story_5068_50681301_36_dialog_content = "(Realmente lamento que tu familia haya tenido que terminar así... Pero confía en mí cuando digo que nada de esto es tu culpa!)",
  ui_story_5068_50681301_37_dialog_content = "(¿Cómo podrías ser la \"hija del desastre\" cuando te has lastimado tanto solo para salvar a tus pacientes? Si acaso, ¡eres un ángel guardián de Umbraton!)",
  ui_story_5068_50681301_38_dialog_content = "(Si no me crees, intenta usar tus poderes para rescatar a Isa ¡ahora mismo!)",
  ui_story_5068_50681301_39_dialog_content = "(Mis poderes... ¿Realmente puedo usarlos para salvarla?)",
  ui_story_5068_50681301_40_dialog_content = "(Si lucho con todo mi poder—)",
  ui_story_5068_50681301_41_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5068_50681301_42_dialog_content = "D... Director...",
  ui_story_5068_50681301_43_dialog_content = "¡Puedes hacerlo, Rebecca!",
  ui_story_5068_50681301_44_dialog_content = "Isa!!!",
  ui_story_5068_50681301_45_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_46_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5068_50681301_47_dialog_content = "Deja de resistirte ya. Es tan peligroso como inútil.",
  ui_story_5068_50681301_48_dialog_content = "Ni siquiera tú puedes curar una herida de bala en la cabeza, Rebecca.",
  ui_story_5068_50681301_49_dialog_content = "Mmm, mmm—!!",
  ui_story_5068_50681301_50_dialog_content = "¡...!",
  ui_story_5068_50681301_51_dialog_content = "Isa—¡No!",
  ui_story_5068_50681301_52_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5068_50681301_53_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5068_50681301_54_dialog_content = "Urgh—! ¿Quién hizo eso?!",
  ui_story_5068_50681301_55_dialog_content = "¡Ahora es el tiempo, hermanos!",
  ui_story_5068_50681301_56_dialog_content = "¡Sí!",
  ui_story_5068_50681301_57_dialog_content = "...",
  ui_story_5068_50681301_58_dialog_content = "¡¿?!",
  ui_story_5068_50681301_59_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_5068_50681301_60_dialog_content = "¡Eres tú! ¿Cómo te atreves a dispararme, Eleanor—!!!",
  ui_story_5068_50681301_61_dialog_content = "¿Qué? ¿Escuchaste todo? ¿O conté la historia mal?",
  ui_story_5068_50681301_62_dialog_content = "¡¡Eso es suficiente!!",
  ui_story_5068_50681301_63_dialog_content = "Perdón por llegar tan tarde, señorita Rebecca. ¿Estás bien?",
  ui_story_5068_50681301_64_dialog_content = "Cuando regresé al Gremio de Explorador Nublar, todo lo que encontré fue una habitación vacía y una nota de rescate... Así que vine aquí lo más rápido que pude.",
  ui_story_5068_50681301_65_dialog_content = "Estoy bien, Eleanor, pero por favor ve a ver a Isa.",
  ui_story_5068_50681301_66_dialog_content = "Isa! ¿Estás bien?!",
  ui_story_5068_50681301_67_dialog_content = "Estábamos buscándote cuando Eleanor nos dijo que te habían secuestrado, ¡así que nos apresuramos a venir aquí con ella!",
  ui_story_5068_50681301_68_dialog_content = "... ¡Estoy bien! De hecho... ¡Estoy mejor que bien! Es hora de devolverles la hospitalidad a los Lobos Negros, ¡así que prepárate para una pelea!",
  ui_story_5068_50681301_69_dialog_content = "Pero te ves realmente herido, Isa! ¡Deberíamos salir de aquí mientras tengamos la oportunidad!",
  ui_story_5068_50681301_70_dialog_content = "PlayerName tiene razón... ¡Despejaré un camino para salir de aquí!",
  ui_story_5068_50681301_71_dialog_content = "¡Estoy contigo, señorita Rebecca!",
  ui_story_5068_50681301_72_dialog_content = "Está bien, también apoyaré a todos en la batalla.",
  ui_story_5068_50681302_1_dialog_content = "Perdónenos, Director... Los dejamos escapar.",
  ui_story_5068_50681302_2_dialog_content = "...",
  ui_story_5068_50681302_3_dialog_content = "¿Director?",
  ui_story_5068_50681302_4_dialog_content = "Está bien. No me importa jugar con ellos un poco más, ya que disfrutan tanto luchando.",
  ui_story_5068_50681302_X4_dialog_content = "Puedo contar con una mano la cantidad de lugares a los que pueden ir. Preparémosles un buen regalo de bienvenida antes de ir allá...",
  ui_story_5068_50681302_X5_dialog_content = "Es hora de jugar nuestra carta de triunfo, ¡ve a prepararla!",
  ui_story_5068_50681302_5_dialog_content = "Hoy no será diferente al día en que murió la Familia Svanedona... ¡Todo es porque ustedes, tontos, me obligaron a actuar!",
  ui_story_5068_50681302_6_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5068_50681302_7_dialog_content = "Uf—Yo... No creo que nos sigan persiguiendo...",
  ui_story_5068_50681302_X7_dialog_content = "Debo decir, ¡ustedes mercenarios realmente saben cómo defenderse! Pero, ¿no deberíamos preocuparnos por los chicos que cubrieron nuestra huida...?",
  ui_story_5068_50681302_X8_dialog_content = "Somos todos profesionales, no hay necesidad de preocuparse por ellos. Se reagruparán con nosotros en poco tiempo.",
  ui_story_5068_50681302_8_dialog_content = "Hemos estado corriendo durante tanto tiempo... ¿Todos siguen bien?",
  ui_story_5068_50681302_9_dialog_content = "... ¡No te detengas todavía! Este lugar no es seguro y Arte no nos dejará ir tan fácilmente.",
  ui_story_5068_50681302_10_dialog_content = "...",
  ui_story_5068_50681302_11_dialog_content = "¿Cómo te encuentras, Rebecca? ¡Incluso con mi herida, te ves peor que yo!",
  ui_story_5068_50681302_12_dialog_content = "Estaré... estaré bien. Solo vayamos a un lugar seguro primero...",
  ui_story_5068_50681302_13_dialog_content = "Solo espera, señorita Rebecca!",
  ui_story_5068_50681302_14_dialog_content = "Hay algunos almacenes abandonados más adelante. ¡Podemos parar y tomar un respiro allí!",
  ui_story_5068_50681302_15_dialog_content = "Mis hombres y yo estaremos atentos, así que adelante y descansen un poco. No nos quedaremos aquí mucho más tiempo.",
  ui_story_5068_50681302_16_dialog_content = "Déjame ayudarte a sentarte, señorita Rebecca...",
  ui_story_5068_50681302_17_dialog_content = "¡Espera! Respóndeme una pregunta ahora mismo: ¿quién demonios eres tú—",
  ui_story_5068_50681302_18_dialog_content = "Isa!",
  ui_story_5068_50681302_19_dialog_content = "...",
  ui_story_5068_50681302_20_dialog_content = "Solo detente, Isa... No quiero saber.",
  ui_story_5068_50681302_21_dialog_content = "Eleanor arriesgó su vida para salvarme de los Lobos Negros dos veces... Eso es todo lo que necesito saber... Nada más.",
  ui_story_5068_50681302_22_dialog_content = "¡Pero también es culpa de ella! ¡Ella es la razón por la que perdimos a nuestra familia!",
  ui_story_5068_50681302_23_dialog_content = "Eso no es el Eleanor que conozco...",
  ui_story_5068_50681302_24_dialog_content = "La Eleanor que conozco me cuida cuando pierdo el conocimiento... Ella venda las heridas de nuestros pacientes y hace sopa para los niños en nuestra clínica. Ella—",
  ui_story_5068_50681302_25_dialog_content = "¡Señorita Rebecca!",
  ui_story_5068_50681302_26_dialog_content = "Me conmueve que pienses tan amablemente de mí... Pero cuanto más mencionas estas cosas, más culpa siento.",
  ui_story_5068_50681302_27_dialog_content = "Yo... tengo una confesión que hacer—",
  ui_story_5068_50681302_28_dialog_content = "No... Eleanor, por favor...",
  ui_story_5068_50681302_29_dialog_content = "Todo es cierto... Cada palabra.",
  ui_story_5068_50681302_30_dialog_content = "¡¿Tú...?!",
  ui_story_5068_50681302_31_dialog_content = "Es cierto que solía ser miembro de los Lobos Negros y que me enviaron a infiltrarme en la Familia Svanedona.",
  ui_story_5068_50681302_32_dialog_content = "La razón por la que me acerqué tanto a ti fue para obtener información de ella.",
  ui_story_5068_50681302_33_dialog_content = "Lo siento mucho, señorita Rebecca.",
  ui_story_5068_50681401_1_dialog_content = "No puedo recordar el rostro de ninguno de mis padres. Desde que tengo memoria, vivía día a día, robando lo que podía para alimentarme. Incluso las otras personas en las barriadas no podían soportar verme.",
  ui_story_5068_50681401_2_dialog_content = "Un día estaba tirado en un montón de basura, muriendo de hambre... Fue entonces cuando los Lobos Negros me acogieron.",
  ui_story_5068_50681401_3_dialog_content = "En ese entonces, los Lobos Negros eran completamente diferentes a lo que son hoy. Eran como una gran familia, y yo estaba lejos de ser el único niño indefenso entre ellos.",
  ui_story_5068_50681401_4_dialog_content = "Arte fue quien lideró nuestra lucha por la supervivencia y nos dijo que siempre nos cuidáramos mutuamente.",
  ui_story_5068_50681401_5_dialog_content = "Lentamente pero con seguridad, cada vez más personas se unieron a los Lobos Negros. Los objetivos de Arte también se volvieron más ambiciosos, razón por la cual comenzamos a luchar contra otras pandillas.",
  ui_story_5068_50681401_6_dialog_content = "Me llené de furia al escuchar que la Familia Svanedona había lastimado a mis hermanos y hermanas en los Lobos Negros. Pensé que los Svanedonas no eran más que delincuentes que intimidaban a los débiles... Después de todo, ¿quién podría perdonar a personas por lastimar a mi propia familia?",
  ui_story_5068_50681401_7_dialog_content = "Poco después, Arte me dio la orden de infiltrarme en la Familia Svanedona y acercarme a la señorita Rebecca. Se suponía que debía esperar el momento perfecto para secuestrarla...",
  ui_story_5068_50681401_8_dialog_content = "Pero después de pasar día tras día feliz contigo, algo extraño comenzó a apoderarse de mí...",
  ui_story_5068_50681401_9_dialog_content = "Me trataste como si fuera de la familia. Tu confianza y amabilidad también llegaron al corazón del resto de tu familia.",
  ui_story_5068_50681401_10_dialog_content = "...",
  ui_story_5068_50681401_11_dialog_content = "Para los Lobos Negros, lesionarse es vergonzoso, pero contigo y tu familia fue diferente. Siempre que me lastimaba, nunca respondían con burlas, sino con amor y amabilidad.",
  ui_story_5068_50681401_12_dialog_content = "Para mí, eso es lo que realmente significa ser una familia.",
  ui_story_5068_50681401_13_dialog_content = "Antes de saber cuál era el verdadero objetivo de Arte, intenté convencer a Arte de acercarse a ti de una manera más pacífica. Desafortunadamente, todos sabemos cómo terminó eso.",
  ui_story_5068_50681401_14_dialog_content = "Estaba en conflicto y no sabía qué hacer: no podía traicionar a los Lobos Negros, pero tampoco podía obligarme a lastimar a la señorita Rebecca de ninguna manera.",
  ui_story_5068_50681401_15_dialog_content = "Al final, tomé una decisión que lamentaré por el resto de mi vida—",
  ui_story_5068_50681401_16_dialog_content = "Me escapé.",
  ui_story_5068_50681401_17_dialog_content = "Y debido a que escapé, Arte y los Lobos Negros tuvieron la oportunidad de atacar a la familia Svanedona.",
  ui_story_5068_50681401_18_dialog_content = "Esperaba con todas mis fuerzas que la señorita Rebecca estuviera bien. Cuando finalmente regresé, la encontré cara a cara con un Arte sediento de sangre.",
  ui_story_5068_50681401_19_dialog_content = "Estaba gritando como loca a todo pulmón, diciendo cosas como: \"¡¿Cómo te atreves a menospreciarme?! ¡¿Al destino de los Lobos Negros?!\" Era una persona completamente diferente a la Arte que conocí en el pasado.",
  ui_story_5068_50681401_20_dialog_content = "Siempre fue muy protectora de su familia en el pasado. No tenía idea de qué había pasado para que cambiara así; todo lo que sabía era que necesitaba salvar a la señorita Rebecca y sacarla de allí de inmediato.",
  ui_story_5068_50681401_21_dialog_content = "...",
  ui_story_5068_50681401_22_dialog_content = "¿Crees que decir algo de esto nos hará perdonarte? Rebecca y yo perdimos a toda nuestra familia, ¡asesino!",
  ui_story_5068_50681401_23_dialog_content = "...",
  ui_story_5068_50681401_24_dialog_content = "Rebecca, sé que no merezco tu perdón, mucho menos toda la confianza y amabilidad que me has mostrado en el último año.",
  ui_story_5068_50681401_25_dialog_content = "Una persona como yo no tiene derecho a vivir...",
  ui_story_5068_50681401_26_dialog_content = "Entonces, por favor solo mátame, señorita Rebecca!",
  ui_story_5068_50681401_27_dialog_content = "...",
  ui_story_5068_50681401_28_dialog_content = "¡Cómo te atreves! Sabes que Rebecca nunca haría algo así. ¡Incluso ahora, sigues aprovechándote de su bondad, tú—",
  ui_story_5068_50681401_29_dialog_content = "Eleanor, ¿alguna vez pensaste en qué tipo de vida tendría Rebecca si te matara?",
  ui_story_5068_50681401_30_dialog_content = "¡Pero no merezco algo mejor!",
  ui_story_5068_50681401_31_dialog_content = "Si eso la hiciera sentir mejor, aunque sea un poquito...",
  ui_story_5068_50681401_32_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5068_50681401_33_dialog_content = "¿Qué está pasando ahí fuera...?",
  ui_story_5068_50681401_34_dialog_content = "¡Alguien se acerca! ¡Necesitamos salir de aquí!",
  ui_story_5068_50681401_35_dialog_content = "No... ¿Cómo los Lobos Negros nos alcanzaron tan rápido?!",
  ui_story_5068_50681401_36_dialog_content = "¡Vamos, señorita Rebecca!",
  ui_story_5068_50681401_37_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5068_50681401_38_dialog_content = "¡Aquí!",
  ui_story_5068_50681401_39_dialog_content = "Eso fue más fácil de lo que esperaba. Parece que nuestro pequeño juego de gato y ratón ha terminado ahora.",
  ui_story_5068_50681401_40_dialog_content = "Basta de tanto luchar sin sentido. Ven tranquilamente y quizás deje algunos cadáveres para enterrar después.",
  ui_story_5068_50681401_41_dialog_content = "¡Nadie va a ir tranquilamente con escoria como tú! ¡Atrápenla, hombres!",
  ui_story_5068_50681401_42_dialog_content = "¡Entendido!",
  ui_story_5068_50681401_43_dialog_content = "¡Cuidado! ¡Lleva algo peligroso en sus manos!",
  ui_story_5068_50681402_1_dialog_content = "<color=#e8d9bb>Silbido—</color>",
  ui_story_5068_50681402_2_dialog_content = "Tose, tose.",
  ui_story_5068_50681402_3_dialog_content = "Esta neblina negra...",
  ui_story_5068_50681402_4_dialog_content = "¿Qué está pasando? ¿No se supone que Rebecca es inmune a la niebla negra?!",
  ui_story_5068_50681402_5_dialog_content = "Realmente te compadezco, Rebecca. Nacido en una familia con habilidades innatas tan increíbles... Me sorprende que ninguno de ustedes haya pensado en investigar los secretos detrás de sus poderes.",
  ui_story_5068_50681402_6_dialog_content = "Pero está bien. Ya he hecho gran parte de eso por ti y estoy orgulloso de presentarte los frutos de mi investigación—",
  ui_story_5068_50681402_7_dialog_content = "Una niebla negra capaz de contrarrestar tu veneno.",
  ui_story_5068_50681402_8_dialog_content = "Pero... cómo...",
  ui_story_5068_50681402_9_dialog_content = "Jeje, ¿no crees que hay algo especial en esta neblina? Algo notablemente familiar, ¿quizás?",
  ui_story_5068_50681402_10_dialog_content = "¿Qué... Qué estás tratando de decir...?",
  ui_story_5068_50681402_11_dialog_content = "¿No te recuerda al cálido abrazo de tus padres?",
  ui_story_5068_50681402_12_dialog_content = "¿Qué demonios está hablando esta mujer loca?!",
  ui_story_5068_50681402_13_dialog_content = "A diferencia de tus tacaños familiares, estoy más que feliz de compartir contigo la fórmula de esta niebla negra.",
  ui_story_5068_50681402_14_dialog_content = "Esta niebla... alguna vez fue tu preciado padre/madre.",
  ui_story_5068_50681402_15_dialog_content = "—?!",
  ui_story_5068_50681402_16_dialog_content = "Después de un año completo de investigación, finalmente descubrí el secreto de la familia Svanedona: los padres en su familia tienen un efecto neutralizante e incluso corrosivo en las habilidades de sus descendientes.",
  ui_story_5068_50681402_17_dialog_content = "Es gracias a esto, Rebecca, que puedo mantener tu buen comportamiento. Debería agradecerle a tu padre por ahorrarme tanto esfuerzo.",
  ui_story_5068_50681402_18_dialog_content = "¿C-Cómo pudiste hacer algo tan desalmado? Usar a su familia en su contra...",
  ui_story_5068_50681402_19_dialog_content = "¡Arte! ¿Has... Has perdido la cabeza? ¿No recuerdas lo que siempre nos decías? \"Las peores personas del mundo son aquellas que se aprovechan descaradamente de los débiles.\"",
  ui_story_5068_50681402_20_dialog_content = "¡Mírate ahora! Hasta hace un año todavía sentía algo de simpatía por ti, ya que pensaba que solo buscabas venganza. ¡Pero ahora veo que eres una persona totalmente diferente!",
  ui_story_5068_50681402_21_dialog_content = "¿Qué pudo haberte torcido así? ¿Fue la emoción del poder y matar?",
  ui_story_5068_50681402_22_dialog_content = "O tal vez ¿siempre has sido así? ¿Nos has estado utilizando desde el principio...?",
  ui_story_5068_50681402_23_dialog_content = "Jeje... ¡Jajajaja! ¿Qué sabrías tú?!",
  ui_story_5068_50681402_24_dialog_content = "Te encontré hambriento en la basura, ¡un desdichado al que incluso los perros despreciaban! ¿Dónde estarías ahora si no fuera por mí?!",
  ui_story_5068_50681402_25_dialog_content = "Los Lobos Negros nunca habrían sobrevivido tanto tiempo si no hubiera mentido, engañado y robado en cada paso del camino!",
  ui_story_5068_50681402_26_dialog_content = "¿Por eso convertiste a nuestros hermanos y hermanas en los Lobos Negros en herramientas para tu beneficio personal?!",
  ui_story_5068_50681402_27_dialog_content = "Si es así, entonces traicionarte fue la decisión más inteligente que he tomado en mi vida.",
  ui_story_5068_50681402_28_dialog_content = "¡Basta!",
  ui_story_5068_50681402_29_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5068_50681402_30_dialog_content = "... Los traidores no tienen derecho a criticar a los Lobos Negros.",
  ui_story_5068_50681402_31_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5068_50681402_32_dialog_content = "Je. Parece que tu puntería se ha oxidado, Director.",
  ui_story_5068_50681402_33_dialog_content = "Tsk.",
  ui_story_5068_50681402_34_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_5068_50681402_35_dialog_content = "No... Detente... Urgh...",
  ui_story_5068_50681402_36_dialog_content = "No tiene sentido luchar hasta el amargo final, Rebecca.",
  ui_story_5068_50681402_37_dialog_content = "Muertos o vivos, aún puedo usarlos para continuar mi investigación, ¡así que no digan que nunca les di una oportunidad de sobrevivir! ¡Todos ustedes van a morir aquí!",
  ui_story_5068_50681402_38_dialog_content = "... ¡Cuidado, señorita Rebecca!",
  ui_story_5068_50681402_39_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5068_50681402_40_dialog_content = "<color=#e8d9bb>¡Esfuerzo!</color>",
  ui_story_5068_50681402_41_dialog_content = "<size=50>Eleanor?!</size>",
  ui_story_5068_50681402_42_dialog_content = "No... ¿Por qué ustedes simplemente están parados ahí? ¡El enemigo está justo enfrente, así que abran fuego!",
  ui_story_5068_50681402_43_dialog_content = "¡Fuego!",
  ui_story_5068_50681402_44_dialog_content = "¡Vamos a por ellos!",
  ui_story_5068_50681402_45_dialog_content = "¡¡¡Sí señor!!!",
  ui_story_5068_50681402_46_dialog_content = "Eleanor... ¿Puedes escucharme...?",
  ui_story_5068_50681402_47_dialog_content = "Rebecca... Nunca pensé que volvería a escuchar... que pronuncias mi nombre... Pensé que me abandonarías.",
  ui_story_5068_50681402_48_dialog_content = "Pero si puedo morir... en tus brazos... entonces no tengo arrepentimientos...",
  ui_story_5068_50681402_49_dialog_content = "¡N-No digas cosas así! Puedo sanarte, solo dame algo de tiempo...",
  ui_story_5068_50681402_50_dialog_content = "No... Es demasiado tarde para mí... No malgastes tus poderes... en alguien como yo...",
  ui_story_5068_50681402_51_dialog_content = "Simplemente sal de aquí... y encuentra un lugar... donde nunca te encuentren...",
  ui_story_5068_50681402_52_dialog_content = "No olvides que soy médico... nunca podría abandonar a ninguno de mis pacientes... especialmente a ti.",
  ui_story_5068_50681402_53_dialog_content = "Argh! Aún no puedo usar todo mi poder... Pero, ¿cómo se supone que debo recuperarme...?",
  ui_story_5068_50681402_54_dialog_content = "Espera... ¡Eso es! ¡Los frascos y botellas en la clínica! Solo necesito volver y reponer mi veneno y suero, y luego puedo—",
  ui_story_5068_50681402_55_dialog_content = "La clínica... no es segura...",
  ui_story_5068_50681402_56_dialog_content = "No hay necesidad... de arriesgar tu vida por mí...",
  ui_story_5068_50681402_57_dialog_content = "Simplemente... corre...",
  ui_story_5068_50681402_58_dialog_content = "Ella va tras de ti, Rebecca! Mi equipo cubrirá a Eleanor mientras tú escapas.",
  ui_story_5068_50681402_59_dialog_content = "PlayerName, lleva a Rebecca y encuentra una salida de aquí! ¡Cuento contigo!",
  ui_story_5068_50681402_60_dialog_content = "¡De acuerdo! ¡Vamos, Rebecca!",
  ui_story_5068_50681402_61_dialog_content = "¿Huyendo, verdad?",
  ui_story_5068_50681402_62_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5068_50681402_63_dialog_content = "Yo... ¡No te dejaré interponerte en el camino de Rebecca! Tu pelea... ¡es conmigo!",
  ui_story_5068_50681402_64_dialog_content = "No te halagues a ti mismo.",
  ui_story_5068_50681402_65_dialog_content = "<color=#e8d9bb>¡Bang, bang!!!</color>",
  ui_story_5068_50681402_66_dialog_content = "Urgh...",
  ui_story_5068_50681402_67_dialog_content = "—!!!",
  ui_story_5068_50681402_68_dialog_content = "C... Corre...",
  ui_story_5068_50681402_69_dialog_content = "Eleanor...",
  ui_story_5068_50681402_70_dialog_content = "... ¡Todos retírense! ¡Salgan de aquí, Rebecca!",
  ui_story_5068_50681402_71_dialog_content = "¡Hraaagh—!!",
  ui_story_5068_50681402_72_dialog_content = "Tos...",
  ui_story_5068_50681402_73_dialog_content = "¡Cómo te atreves a morderme!",
  ui_story_5068_50681402_74_dialog_content = "¡Estén atentos, todos ustedes! Así es como tratamos a los traidores—",
  ui_story_5068_50681402_75_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang! ¡Bang! ¡Bang!</color>",
  ui_story_5068_50681402_76_dialog_content = "...",
  ui_story_5068_50681402_77_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5068_50681402_78_dialog_content = "¡Ah—! ¿Papá? ¡¡¡Papá!!!",
  ui_story_5068_50681402_79_dialog_content = "Corre... Apúrate...",
  ui_story_5068_50681402_80_dialog_content = "Rebecca... ¡Corre!",
  ui_story_5068_50681402_81_dialog_content = "<color=#e8d9bb>¡¡¡砰砰砰砰砰砰!!!</color>",
  ui_story_5068_50681402_82_dialog_content = "Rebecca!",
  ui_story_5068_50681402_83_dialog_content = "¡No mires atrás, Rebecca! ¿Me escuchas?!",
  ui_story_5068_50681402_84_dialog_content = "... No permitas que el sacrificio de Eleanor sea en vano.",
  ui_story_5068_50681402_85_dialog_content = "¿Dónde está Eleanor, Isa? ¿No prometiste salvarla?",
  ui_story_5068_50681402_86_dialog_content = "Ella está... más allá de salvar, Rebecca...",
  ui_story_5068_50681402_87_dialog_content = "¿Pero cómo podría ser eso? Ni siquiera he comenzado a tratarla todavía...",
  ui_story_5068_50681402_88_dialog_content = "N-No... No voy a abandonar a Eleanor así...",
  ui_story_5068_50681402_89_dialog_content = "Rebecca... Ya es demasiado tarde.",
  ui_story_5068_50681402_90_dialog_content = "PlayerName... También crees que fallé como médico, ¿verdad...?",
  ui_story_5068_50681402_91_dialog_content = "Todo es mi culpa por no poder usar mis poderes. Si no fuera por mí, Eleanor todavía estaría...",
  ui_story_5068_50681402_92_dialog_content = "Todo mi esfuerzo, toda mi investigación, todo fue para poder curar y proteger a los demás...",
  ui_story_5068_50681402_93_dialog_content = "Entonces, ¿por qué... por qué sigo siendo tan inútil? ¿Por qué tiene que ser así?",
  ui_story_5068_50681402_94_dialog_content = "Espera, es cierto. Todavía tengo todas esas botellas de veneno y suero. Si puedo usarlos para recuperar mis poderes, puedo salvar a Eleanor y a todos los demás...!",
  ui_story_5068_50681402_95_dialog_content = "¿Eh? ¿A dónde crees que vas, Rebecca?!",
  ui_story_5068_50681501_1_dialog_content = "¡Espera, Rebecca! ¿Adónde vas?!",
  ui_story_5068_50681501_2_dialog_content = "Nos costó todo lo que teníamos para escapar, y los Lobos Negros podrían aparecer en cualquier momento. ¡Necesitamos apresurarnos a regresar al Gremio Cloudrover!",
  ui_story_5068_50681501_3_dialog_content = "Tengo que... reponer mi veneno... y mi suero...",
  ui_story_5068_50681501_4_dialog_content = "... Por favor, no me asustes así, Rebecca...",
  ui_story_5068_50681501_5_dialog_content = "Sé que estás sufriendo mucho después de perder a Eleanor, ¡pero ella hizo lo que hizo para salvarte! Así que por favor, solo mírame.",
  ui_story_5068_50681501_6_dialog_content = "Tengo que... reponer mi veneno...",
  ui_story_5068_50681501_7_dialog_content = "No para de hablar sobre reponer su veneno... Creo que intenta regresar a la clínica.",
  ui_story_5068_50681501_8_dialog_content = "Pero, ¿ella... realmente estará bien así?",
  ui_story_5068_50681501_9_dialog_content = "...",
  ui_story_5068_50681501_10_dialog_content = "Rebecca!",
  ui_story_5068_50681501_11_dialog_content = "<color=#e8d9bb>A cierta distancia</color>",
  ui_story_5068_50681501_12_dialog_content = "Director... ¿Estás seguro de que estás bien?",
  ui_story_5068_50681501_13_dialog_content = "¿Crees que estas heridas pueden detenerme? ¿Has olvidado cómo logramos sobrevivir todo este tiempo?",
  ui_story_5068_50681501_14_dialog_content = "Dime, ¿ya está listo?",
  ui_story_5068_50681501_15_dialog_content = "Sí, Director.",
  ui_story_5068_50681501_16_dialog_content = "Ya es suficiente. Estoy harto de lidiar con todo esto sin sentido. Tomaré lo que quiero una vez que ella haya sido destruida.",
  ui_story_5068_50681501_17_dialog_content = "Me pregunto... ¿Harán mis fuegos artificiales que este montón de basura sea más hermoso?",
  ui_story_5068_50681501_18_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_5068_50681501_19_dialog_content = "¡Ahh—!",
  ui_story_5068_50681501_20_dialog_content = "Rebecca! Isa!",
  ui_story_5068_50681501_21_dialog_content = "*Tosiendo* ... ¿Isa?!",
  ui_story_5068_50681501_22_dialog_content = "...",
  ui_story_5068_50681501_23_dialog_content = "Isa¡Despierta...!",
  ui_story_5068_50681501_24_dialog_content = "Mi veneno... salvará a todos...",
  ui_story_5068_50681501_25_dialog_content = "¡Detente, Rebecca! ¡La clínica va a explotar! ¡No entres ahí!!!",
  ui_story_5068_50681501_26_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5068_50681501_27_dialog_content = "Explotó... Jeje...",
  ui_story_5068_50681501_28_dialog_content = "Eleanor... Al final... ni siquiera pude salvar nuestra clínica...",
  ui_story_5068_50681501_29_dialog_content = "...? ¡M-Mis pendientes! ¿Dónde están los pendientes que me dio Eleanor?!",
  ui_story_5068_50681501_30_dialog_content = "...",
  ui_story_5068_50681501_31_dialog_content = "Se fueron... todo se ha ido.",
  ui_story_5068_50681501_32_dialog_content = "¿Rebecca?!",
  ui_story_5068_50681501_33_dialog_content = "¿Por qué? ¿Por qué tiene que ser así...?",
  ui_story_5068_50681501_34_dialog_content = "Mi familia se ha ido, Eleanor se ha ido, nuestra casa se ha ido, e incluso los pendientes que ella hizo para mí se han ido—no me queda nada.",
  ui_story_5068_50681501_35_dialog_content = "Eso no es cierto, Rebecca! ¿Qué hay de Isa? ¡Todavía tienes a tu hermana!",
  ui_story_5068_50681501_36_dialog_content = "Oh...",
  ui_story_5068_50681501_37_dialog_content = "Re... becca...",
  ui_story_5068_50681501_38_dialog_content = "¡Gracias a Dios, sigue viva!",
  ui_story_5068_50681501_39_dialog_content = "Es demasiado peligroso allá abajo, Rebecca! Isa todavía te necesita, ¡así que por favor regresa!",
  ui_story_5068_50681501_40_dialog_content = "Isa... me necesita...?",
  ui_story_5068_50681501_41_dialog_content = "¡M-Mi hermana todavía me necesita!",
  ui_story_5068_50681501_42_dialog_content = "(¿Estás seguro? Después de todo, ¿quién podría necesitar a alguien que solo trae dolor y sufrimiento a dondequiera que va?)",
  ui_story_5068_50681501_43_dialog_content = "Fui yo... Yo soy quien hizo todo esto...",
  ui_story_5068_50681501_44_dialog_content = "(Tu supuesta \"dádiva\" es la causa de todo este sufrimiento. ¿Realmente crees que mereces seguir viviendo?)",
  ui_story_5068_50681501_45_dialog_content = "Así es... Mi poder es lo que atrajo a los Lobos Negros a la puerta de nuestra familia. Por mi culpa, todos están...",
  ui_story_5068_50681501_46_dialog_content = "Mi poder es lo que creó la niebla negra que enfermó a tanta gente en los barrios bajos...",
  ui_story_5068_50681501_47_dialog_content = "(¿Y qué hay de Eleanor? Su muerte también está en tus manos, y no olvidemos a tu hermana, que ya tiene un pie en la tumba.)",
  ui_story_5068_50681501_48_dialog_content = "(¿No crees sinceramente que puedas derrotar a los Lobos Negros con un poder maldito como el tuyo, verdad?)",
  ui_story_5068_50681501_49_dialog_content = "(Y aunque lo hagas, ¿quién puede decir que alguien más no buscará tu poder? Ya perdiste Eleanor; ¿quién pagará el precio la próxima vez? ¿La gente en las barriadas? ¿Isa?)",
  ui_story_5068_50681501_50_dialog_content = "¡No! No dejaré que eso suceda... Pero ¿cómo... Cómo puedo protegerlos?",
  ui_story_5068_50681501_51_dialog_content = "(Jejeje, la respuesta es simple. Todo lo que tienes que hacer...)",
  ui_story_5068_50681501_52_dialog_content = "(Elimina tu existencia del mundo. Una vez que te hayas ido, todo estará bien...)",
  ui_story_5068_50681501_53_dialog_content = "*Tosiendo* Ugh... ¡Eso duele!",
  ui_story_5068_50681501_54_dialog_content = "¡Estás despierto, Isa!",
  ui_story_5068_50681501_55_dialog_content = "Idiota... Deja de preocuparte por mí... Rebecca es quien necesita... Argh—",
  ui_story_5068_50681501_56_dialog_content = "¡Deja de moverte! Solo vas a perder más sangre si lo haces...",
  ui_story_5068_50681501_57_dialog_content = "Tienes que detenerla... Parece que está a punto de hacer algo imprudente...",
  ui_story_5068_50681501_58_dialog_content = "Yo-Yo soy su hermana... Sé cómo es ella, ahora ve a detenerla...",
  ui_story_5068_50681501_59_dialog_content = "¡Lo tengo!",
  ui_story_5068_50681501_60_dialog_content = "Rebecca!",
  ui_story_5068_50681501_61_dialog_content = "Rebecca? ¿Qué estás...?",
  ui_story_5068_50681501_62_dialog_content = "... ¡No te acerques más!",
  ui_story_5068_50681501_63_dialog_content = "Es peligroso aquí.",
  ui_story_5068_50681501_64_dialog_content = "¿Qué piensas hacer?",
  ui_story_5068_50681501_65_dialog_content = "... Lo único que puedo hacer para dejar de lastimar a las personas a mi alrededor.",
  ui_story_5068_50681501_66_dialog_content = "¡¿T-Tú estás absorbiendo todo este veneno?!",
  ui_story_5068_50681501_67_dialog_content = "Pero tu cuerpo... ¿Realmente puede manejar tanto?!",
  ui_story_5068_50681501_68_dialog_content = "Estaré bien... No te preocupes. No duele en absoluto...",
  ui_story_5068_50681501_69_dialog_content = "¡Um...!",
  ui_story_5068_50681501_70_dialog_content = "¡Basta, Rebecca! ¡Morirás si no lo haces!",
  ui_story_5068_50681501_71_dialog_content = "Así es... Lo hago por el bien de todos...",
  ui_story_5068_50681501_72_dialog_content = "PlayerName... Debería haber muerto hace mucho tiempo. No sé qué me hizo pensar que podría proteger a alguien...",
  ui_story_5068_50681501_73_dialog_content = "¡No digas eso! ¡Me prometiste que no te lastimarías más!",
  ui_story_5068_50681501_74_dialog_content = "Je, supongo que estoy faltando a mi palabra... Esto es Umbraton, después de todo. No puedes creer todo lo que escuchas en esta ciudad.",
  ui_story_5068_50681501_75_dialog_content = "Umbraton no tiene nada que ver con esto, Rebecca! Tú no eres ese tipo de persona, ¡así que ya basta! ¡Piensa en Isa! ¡Finalmente tienes la oportunidad de estar con tu hermana de nuevo!",
  ui_story_5068_50681501_76_dialog_content = "Ugh... Tos, tos...",
  ui_story_5068_50681501_77_dialog_content = "Isa... Perdón, pero... ¿Podrías... vigilarla por mí...?",
  ui_story_5068_50681501_78_dialog_content = "Por favor dile que lo siento... Y que esta es la única manera de detener todo. También lo hago por ella.",
  ui_story_5068_50681501_79_dialog_content = "(Eso es. Si quieres que esto termine, ¡sigue absorbiendo este veneno! ¡Absórbelo todo!!!)",
  ui_story_5068_50681501_80_dialog_content = "PlayerName... Por favor... Saca a mi hermana de aquí.",
  ui_story_5068_50681501_81_dialog_content = "Rebecca...",
  ui_story_5068_50681501_82_dialog_content = "Vamos... ¡Ahora—!",
  ui_story_5068_50681501_83_dialog_content = "¡Ahhhh—!!!",
  ui_story_5068_50681501_84_dialog_content = "Debería ser suficiente, Rebecca...",
  ui_story_5068_50681501_85_dialog_content = "Déjame el resto a mí.",
  ui_story_5068_50681501_86_dialog_content = "¡Director! Rebecca sigue viva y parece que ha absorbido una gran cantidad de veneno.",
  ui_story_5068_50681501_87_dialog_content = "¡¿Pero cómo?! ¿Dónde pudo haber encontrado tanto veneno...?",
  ui_story_5068_50681501_88_dialog_content = "Es por esos frascos rotos... ¡Su cuerpo está empezando a transformarse al absorber tanto de eso!",
  ui_story_5068_50681501_89_dialog_content = "... Entonces, ¿está usando el veneno de esos frascos como un \"antídoto\"?",
  ui_story_5068_50681501_90_dialog_content = "No creo que pueda mantenerla bajo control una vez que termine de absorber todo ese veneno... Parece que—",
  ui_story_5068_50681501_91_dialog_content = "\"Parece que mi única opción es escapar.\" ¿Eso es lo que ibas a decir?",
  ui_story_5068_50681501_92_dialog_content = "Sheol...",
  ui_story_5068_50681501_93_dialog_content = "Evalúa la situación alrededor de la clínica e infórmame. ¡Cuídate ahí fuera!",
  ui_story_5068_50681501_94_dialog_content = "Sí, Señora Sheol!",
  ui_story_5068_50681501_95_dialog_content = "Entonces, después de todo, aún me recuerdas, Arte de los Lobos Negros.",
  ui_story_5068_50681501_96_dialog_content = "... Una clínica en mal estado como esta no debería interesarte ni al Gremio de Explorador Nublar. ¿Por qué has traído a tu gente aquí?",
  ui_story_5068_50681501_97_dialog_content = "\"¿No debería interesarnos?\", dices? Nuestro pequeño Isa revoltoso está herido en el suelo, y PlayerName parece estar en peligro mortal también.",
  ui_story_5068_50681501_98_dialog_content = "Dime, ¿cómo debo manejar esto de acuerdo con nuestras reglas?",
  ui_story_5068_50681501_99_dialog_content = "De acuerdo con las reglas, el Gremio de Explorador Nublar no tiene autoridad en estos barrios bajos.",
  ui_story_5068_50681501_100_dialog_content = "Lamento decepcionarte, pero a partir de hoy, el Gremio Cloudrover está a cargo de esta clínica.",
  ui_story_5068_50681501_101_dialog_content = "Ahora, ¿cómo piensas compensarnos por lo que le hiciste a uno de nuestros médicos?",
  ui_story_5068_50681501_102_dialog_content = "...",
  ui_story_5068_50681501_103_dialog_content = "¡Lady Sheol! Isa y PlayerName están a salvo por ahora, pero la situación de Rebecca no parece muy buena. ¡El resto de nuestra gente ya se ha retirado!",
  ui_story_5068_50681501_104_dialog_content = "No me digas...",
  ui_story_5068_50681501_105_dialog_content = "¡Señora Sheol! ¡Finalmente estás aquí!",
  ui_story_5068_50681501_106_dialog_content = "L-Lady Sheol! Es Rebecca... Tienes que salvarla—",
  ui_story_5068_50681501_107_dialog_content = "¡Mueran—!!!",
  ui_story_5068_50681501_108_dialog_content = "... Pobre niña. Solo mira lo que le han hecho.",
  ui_story_5068_50681501_109_dialog_content = "¡Director! ¿Deberíamos... retirarnos por ahora?",
  ui_story_5068_50681501_110_dialog_content = "¡No! ¡Usa las bombas de niebla negra!",
  ui_story_5068_50681501_111_dialog_content = "<color=#e8d9bb> Silbido—</color>",
  ui_story_5068_50681501_112_dialog_content = "¿¡No funciona!? ¿Pero cómo—",
  ui_story_5068_50681501_113_dialog_content = "¡ARTE!",
  ui_story_5068_50681501_114_dialog_content = "Tengo un nuevo trabajo para ti, PlayerName! ¡Navega nuestras fuerzas hacia la batalla!",
  ui_story_5068_50681501_115_dialog_content = "Rebecca necesita nuestra ayuda ahora mismo!",
  ui_story_5068_50681501_116_dialog_content = "... ¡E-Entendido!",
  ui_story_5068_50681502_1_dialog_content = "¡Lancen más bombas, tontos! ¡Tiren todo lo que tenemos sobre ella!",
  ui_story_5068_50681502_2_dialog_content = "¡Pero Director! Si usamos tantos a la vez, nuestro equipo de protección no nos salvará. Además, todos ya están...",
  ui_story_5068_50681502_3_dialog_content = "¡No me cuestiones! ¡No podemos dejar que esa mujer loca nos alcance!",
  ui_story_5068_50681502_4_dialog_content = "*Tosiendo* Y-Ya es demasiado tarde, ya lo respiramos... Ugh...",
  ui_story_5068_50681502_5_dialog_content = "...",
  ui_story_5068_50681502_6_dialog_content = "¡Tú! Lleva a algunos de nuestros luchadores y no dejes que Arte escape. El resto de ustedes ayude a limpiar este desastre.",
  ui_story_5068_50681502_7_dialog_content = "¡Entendido!",
  ui_story_5068_50681502_8_dialog_content = "Re... Rebecca...",
  ui_story_5068_50681502_9_dialog_content = "Soy yo... Isa... Por favor despierta...",
  ui_story_5068_50681502_10_dialog_content = "...",
  ui_story_5068_50681502_11_dialog_content = "Urgh... ¿Dónde... estoy...?",
  ui_story_5068_50681502_12_dialog_content = "Rebecca! ¡Por fin estás despierto!",
  ui_story_5068_50681502_13_dialog_content = "¡Gracias a Dios, pensé que te había perdido de nuevo, Rebecca!",
  ui_story_5068_50681502_14_dialog_content = "—¡¡!",
  ui_story_5068_50681502_15_dialog_content = "¡Espera, Rebecca! ¿A-A dónde vas?!",
  ui_story_5068_50681502_16_dialog_content = "¡N-No te acerques a mí!",
  ui_story_5068_50681502_17_dialog_content = "Creo que me convertí en algo más hace un momento... Esta niebla y todas estas personas heridas... ¿Lo hice yo?",
  ui_story_5068_50681502_18_dialog_content = "Todo lo que quería era terminarlo todo, pero en cambio terminé lastimando a todos de nuevo... Realmente soy un caso perdido, ¿verdad? No quiero causar más problemas para todos, así que déjenme en paz—",
  ui_story_5068_50681502_19_dialog_content = "¡No seas estúpido, Rebecca!",
  ui_story_5068_50681502_20_dialog_content = "¡¿Isa?!",
  ui_story_5068_50681502_21_dialog_content = "¡No! ¡Suéltame! Mi cuerpo, está cubierto de veneno.",
  ui_story_5068_50681502_22_dialog_content = "¡No soltaré! ¡Ni siquiera si muero!",
  ui_story_5068_50681502_23_dialog_content = "¿No quieres causar más problemas a todos? ¿Cuándo me convertí en todos? ¡Soy tu hermana! Puedes causarme todos los problemas que quieras, ¡y aún así no me importaría!",
  ui_story_5068_50681502_24_dialog_content = "Decirme que te deje en paz después de buscarte durante tanto tiempo... ¡Eso es algo que me niego a hacer!",
  ui_story_5068_50681502_25_dialog_content = "¿Quieres saber algo? ¡Escribí una lista de todas las cosas que quería hacer contigo el día que nos volviéramos a encontrar! Y déjame decirte, ¡es una lista larga!",
  ui_story_5068_50681502_26_dialog_content = "Quiero seguir comprándote muchas cosas como antes y vistiéndote con ropa bonita. ¡Yo—",
  ui_story_5068_50681502_27_dialog_content = "¡No te perderé nunca más! ¡Tampoco tienes permitido dejarme!",
  ui_story_5068_50681502_28_dialog_content = "¡Esa es una orden de tu hermana mayor, así que tienes que escuchar! ¿Me oyes, Rebecca?!",
  ui_story_5068_50681502_29_dialog_content = "Yo... Yo también quiero eso, Isa. Quiero vivir la vida que acabas de describir, pero ya es demasiado tarde. He absorbido demasiado veneno y pronto estaré...",
  ui_story_5068_50681502_30_dialog_content = "Solo quiero encontrar un lugar tranquilo y vacío donde pueda morir solo.",
  ui_story_5068_50681502_31_dialog_content = "Aun así... ¡Me quedo contigo pase lo que pase!",
  ui_story_5068_50681502_32_dialog_content = "¿Quieres un lugar bonito y tranquilo? Entonces te ayudaré a buscar uno. Después de eso...",
  ui_story_5068_50681502_33_dialog_content = "Después de eso, te haré una corona de flores, como cuando éramos niños... ¡Te haré docenas, no, cientos de ellas! Así que por favor, Rebecca—",
  ui_story_5068_50681502_34_dialog_content = "Necesitas soltarla primero, Isa. De lo contrario, tú...",
  ui_story_5068_50681502_35_dialog_content = "¡No! Ya dije que no soltaré, ¡incluso si me mata!",
  ui_story_5068_50681502_36_dialog_content = "¡Espera!",
  ui_story_5068_50681502_37_dialog_content = "... Se supone que el veneno de Rebecca corroe la carne. Durante nuestra batalla, muchos de nosotros nos quemamos con su veneno.",
  ui_story_5068_50681502_38_dialog_content = "Entonces, ¿cómo puedes sostenerla de manera segura cuando está completamente cubierta de veneno?!",
  ui_story_5068_50681502_39_dialog_content = "... ¿Qué estás diciendo?",
  ui_story_5068_50681502_40_dialog_content = "Espera, ¡tienes razón! La piel de Rebecca se siente perfectamente bien, ¡como siempre!",
  ui_story_5068_50681502_41_dialog_content = "Es posible que realmente hayas heredado una de las habilidades de la Familia Svanedona, Isa... ¡Un antídoto para el veneno de Rebecca, capaz de neutralizar sus efectos!",
  ui_story_5068_50681502_42_dialog_content = "—¡¡!",
  ui_story_5068_50681502_43_dialog_content = "¡No hay tiempo que perder! ¡Intenta hacer algo!",
  ui_story_5068_50681502_44_dialog_content = "¡Está bien!",
  ui_story_5068_50681502_45_dialog_content = "...",
  ui_story_5068_50681502_46_dialog_content = "¿Bien?",
  ui_story_5068_50681502_47_dialog_content = "Pensé que era solo porque Isa me estaba sosteniendo... Pero la quemazón de mi veneno realmente se siente un poco menos intensa...",
  ui_story_5068_50681502_48_dialog_content = "¿Eso significa... que funcionó?",
  ui_story_5068_50681502_49_dialog_content = "¡Sí!",
  ui_story_5068_50681502_50_dialog_content = "¡Oh, gracias a Dios! Nunca lo hubiera imaginado...",
  ui_story_5068_50681502_51_dialog_content = "Pasaste todo ese tiempo tratando a todos, ¡pero ahora es mi turno de cuidarte! No me importa cuánto tiempo tome, ¡no pararé hasta que estés completamente mejor!",
  ui_story_5068_50681502_52_dialog_content = "Isa...",
  ui_story_5068_50681502_53_dialog_content = "Oh espera, eso me recuerda.",
  ui_story_5068_50681502_54_dialog_content = "Encontré estos antes.",
  ui_story_5068_50681502_55_dialog_content = "Estos son... Los pendientes que Eleanor me dio.",
  ui_story_5068_50681502_56_dialog_content = "... ¿Quieres que te ayude a ponértelos?",
  ui_story_5068_50681502_57_dialog_content = "... Sí, por favor.",
  ui_story_5068_50681502_58_dialog_content = "Mmm... Ahora que lo pienso, estos pendientes te quedan realmente bonitos.",
  ui_story_5068_50681502_59_dialog_content = "...",
  ui_story_5068_50681502_60_dialog_content = "Eleanor... Gracias por cuidar tan bien a mi hermana. A partir de ahora, prometo hacer lo mismo.",
  ui_story_5068_50681601_1_dialog_content = "<color=#e8d9bb>Unos días después</color>",
  ui_story_5068_50681601_2_dialog_content = "Aquí está tu recompensa como prometido. Siéntete libre de asegurarte de que todo esté ahí.",
  ui_story_5068_50681601_3_dialog_content = "... Ese trabajo era demasiado peligroso, ya sabes. Y por alguna razón, no pude comunicarme contigo ni siquiera en los peores momentos...",
  ui_story_5068_50681601_4_dialog_content = "El mundo de los negocios puede ser despiadado, pero de alguna manera siempre logras arreglar las cosas, ¿verdad?",
  ui_story_5068_50681601_5_dialog_content = "Es por eso que, como humilde líder del Gremio de Explorador Nublar, lo único que puedo hacer es pedir su paciencia y comprensión.",
  ui_story_5068_50681601_6_dialog_content = "Claro, pero... Solo pensé que mi compensación sería un poco más grande después de lo que pasé.",
  ui_story_5068_50681601_7_dialog_content = "Jeje, negocias aún más duro que Vice cuando tomas el control. Tendré que tener más cuidado contigo de ahora en adelante.",
  ui_story_5068_50681601_8_dialog_content = "Perdóneme, Señora Sheol!",
  ui_story_5068_50681601_9_dialog_content = "Oh, hola, PlayerName! ¿No sabía que estabas aquí?",
  ui_story_5068_50681601_10_dialog_content = "¿Isa? ¿Y Rebecca también?",
  ui_story_5068_50681601_11_dialog_content = "¿Ya te sientes algo mejor?",
  ui_story_5068_50681601_12_dialog_content = "Sí. Gracias a Isa, me siento mucho mejor ahora.",
  ui_story_5068_50681601_13_dialog_content = "Pero aún tienes un largo camino por recorrer antes de estar completamente curado... ¡Argh, si tan solo fuera un poco más fuerte!",
  ui_story_5068_50681601_14_dialog_content = "No digas eso, Isa! Estoy agradecido simplemente por estar juntos de nuevo.",
  ui_story_5068_50681601_15_dialog_content = "Estoy agradecido de ver que nuestro \"doctor sin nombre\" también se está recuperando lentamente.",
  ui_story_5068_50681601_16_dialog_content = "Por favor, no bromees así, Srita. Sheol.",
  ui_story_5068_50681601_17_dialog_content = "Lo siento, no pude evitarlo al verlos a ustedes dos juntos así... Pero ahora que todos los involucrados están aquí, me gustaría informarles mis hallazgos.",
  ui_story_5068_50681601_18_dialog_content = "Después de todo, tienes derecho a saber qué pasó con los Lobos Negros después del incidente.",
  ui_story_5068_50681601_19_dialog_content = "Pero si prefieres no escucharlo...",
  ui_story_5068_50681601_20_dialog_content = "Está bien, Sra. Sheol. Por favor, díganos.",
  ui_story_5068_50681601_21_dialog_content = "Claro. Intentaré hacerlo breve.",
  ui_story_5068_50681601_22_dialog_content = "Ya hemos recolectado suficientes pruebas para implicar a los Lobos Negros en su malvado plan de producir la niebla negra. En cuanto a Arte...",
  ui_story_5068_50681601_23_dialog_content = "Ella también estuvo expuesta a la niebla negra esa noche. Dondequiera que se esté escondiendo, dudo que nos cause más problemas de ahora en adelante.",
  ui_story_5068_50681601_24_dialog_content = "Entonces, ¡ella obtuvo lo que merecía! Bien, ahora puedo respirar un poco más tranquilo.",
  ui_story_5068_50681601_25_dialog_content = "...",
  ui_story_5068_50681601_26_dialog_content = "En cuanto a su clínica, estaría más que dispuesto a ayudar con su reconstrucción.",
  ui_story_5068_50681601_27_dialog_content = "Gracias, pero no gracias, Lady Sheol. Ya has hecho más que suficiente por nosotros.",
  ui_story_5068_50681601_28_dialog_content = "Jeje, esperaba que Rebecca me rechazara, no tú.",
  ui_story_5068_50681601_29_dialog_content = "La verdad es que vinimos a despedirnos hoy, Sra. Sheol.",
  ui_story_5068_50681601_30_dialog_content = "Ya veo... ¿Estás seguro de que no quieres quedarte aquí? No intento obligarte a trabajar para mí ni nada por el estilo; simplemente sería más feliz si los dos se quedaran con el Gremio Cloudrover.",
  ui_story_5068_50681601_31_dialog_content = "Lo dices, pero sabías exactamente lo que pensábamos en el momento en que entramos, ¿verdad, Lady Sheol?",
  ui_story_5068_50681601_32_dialog_content = "Lo vi en tus ojos, para ser precisos... Así que no solo estoy perdiendo a Rebecca, sino también a uno de mis asistentes más útiles. Oh, qué pena.",
  ui_story_5068_50681601_33_dialog_content = "Incluso iba a pedirle a PlayerName que me ayudara a convencerte de que te quedaras, pero el pobre chico no ha dicho una palabra desde que entraste. Debo decir que estoy decepcionado con él.",
  ui_story_5068_50681601_34_dialog_content = "¿Eh? Yo... estoy...",
  ui_story_5068_50681601_35_dialog_content = "Gracias por su generosa oferta, Sra. Sheol. Pero ya hemos tomado una decisión.",
  ui_story_5068_50681601_36_dialog_content = "Y... Gracias también por toda tu ayuda, PlayerName. Si no me hubieras confiado y acompañado desde el principio, no estaría...",
  ui_story_5068_50681601_37_dialog_content = "¡No lo menciones! Aunque si lo piensas, realmente no hice mucho...",
  ui_story_5068_50681601_38_dialog_content = "Entonces, ¿a dónde van a ir ustedes dos después? ¿Ya lo han averiguado?",
  ui_story_5068_50681601_39_dialog_content = "En Umbraton, siempre es mejor no hacer demasiadas preguntas.",
  ui_story_5068_50681601_40_dialog_content = "Parece que las chicas tienen un secreto que guardar.",
  ui_story_5068_50681601_41_dialog_content = "¿E-En serio...? Entonces no preguntaré más. Pero si alguna vez tienes tiempo, deberías venir a visitar Eraveil algún día. El buen clima y el paisaje tranquilo deberían ayudar con la recuperación de Rebecca.",
  ui_story_5068_50681601_42_dialog_content = "Gracias por la invitación, PlayerName. Tengo la sensación... Nos volveremos a ver muy pronto.",
  ui_story_5068_50681601_43_dialog_content = "Uf...",
  ui_story_5068_50681601_44_dialog_content = "A pesar de que sufrimos otra pérdida... El Señor Sombrío debería estar completamente satisfecho con el trabajo del Gremio de Explorador Nublar.",
  ui_story_5068_50681601_45_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_5068_50681601_46_dialog_content = "¿Ya terminaste de limpiar, Isa? ¿Y has visto mis pendientes en algún lugar?",
  ui_story_5068_50681601_47_dialog_content = "¿Eh...? ¿Qué estás mirando?",
  ui_story_5068_50681601_48_dialog_content = "Ji ji ji...",
  ui_story_5068_50681601_49_dialog_content = "¿Es eso... un álbum de fotos? ¿Por qué solo tiene fotos mías? ¿Y cuándo tomaste todas estas?",
  ui_story_5068_50681601_50_dialog_content = "¿Eh? ¿R-Rebecca?! ¿No tocas nunca antes de entrar?!",
  ui_story_5068_50681601_51_dialog_content = "¡Pero sí toqué!",
  ui_story_5068_50681601_52_dialog_content = "E-Entonces deberías haber esperado a que yo respondiera!",
  ui_story_5068_50681601_53_dialog_content = "Bien, lo entiendo.",
  ui_story_5068_50681601_54_dialog_content = "Toc, toc, toc. Hola Isa, ¿puedo entrar?",
  ui_story_5068_50681601_55_dialog_content = "¡Vale, ahora solo me estás tomando el pelo! Pero veamos cómo te gusta esto!",
  ui_story_5068_50681601_56_dialog_content = "Jajajaja—¡Para, eso hace cosquillas! ¡Lo siento, Isa! ¡Por favor, detente!",
  ui_story_5068_50681601_57_dialog_content = "¡No te librarás tan fácilmente! ¡Hora de mi ataque definitivo!",
  ui_story_5068_50681601_58_dialog_content = "... Entonces, ¿qué pasa con todas esas fotos?",
  ui_story_5068_50681601_59_dialog_content = "Realmente no sabes cuándo parar, ¿verdad? Solo quería documentar tu recuperación, así que decidí tomar algunas fotos.",
  ui_story_5068_50681601_60_dialog_content = "Veo. Gracias por hacer eso por mí, Isa...",
  ui_story_5068_50681601_61_dialog_content = "¡Heeheehee! ¡E-En realidad no es nada! Entonces, ¿necesitabas algo?",
  ui_story_5068_50681601_62_dialog_content = "Todavía no puedo encontrar mis pendientes...",
  ui_story_5068_50681601_63_dialog_content = "¡No te preocupes, están justo aquí! Mira, ¡me he ocupado bien de ellos! ¿Quieres ayuda para ponértelos?",
  ui_story_5068_50681601_64_dialog_content = "Isa... ¿Realmente hice algo para merecer que Eleanor sacrificara su vida por mí?",
  ui_story_5068_50681601_65_dialog_content = "No lo sé. Pero ya que ella estaba dispuesta a llegar tan lejos, debes haber hecho algo.",
  ui_story_5068_50681601_66_dialog_content = "Al menos eso es lo que pienso.",
  ui_story_5068_50681601_67_dialog_content = "...",
  ui_story_5068_50681601_68_dialog_content = "¡Oh, cierto, casi lo olvido! ¿Ya se te ocurrió un nombre para la nueva clínica?",
  ui_story_5068_50681601_69_dialog_content = "Todavía no... Pero sinceramente, ¿por qué no lo llamamos \"La Clínica Sin Nombre\"?",
  ui_story_5068_50681601_70_dialog_content = "¡Bul! ¡Bul!",
  ui_story_5068_50681601_71_dialog_content = "Mi lady... No puedo aguantar mucho más... Pero sé que tú puedes salvarme...",
  ui_story_5068_50681601_72_dialog_content = "... ¿Salvarte? No puedo pensar en una razón para hacer eso.",
  ui_story_5068_50681601_73_dialog_content = "T-Todavía puedo ser útil para ti... Los Lobos Negros y la niebla negra...",
  ui_story_5068_50681601_74_dialog_content = "Sí, tienes razón.",
  ui_story_5068_50681601_75_dialog_content = "Urgh—Entonces—",
  ui_story_5068_50681601_76_dialog_content = "Tu error la última vez fue meterte en una pelea con alguien muy fuera de tu liga.",
  ui_story_5068_50681601_77_dialog_content = "Y... ¿Quieres decir Sheol... Y el Gremio de Explorador Nublar?",
